// Üretilen dosya: tool/ozgun/uret.py. Tarih · Türk-İslam devletleri ve Selçuklular (orta).
const ozHistory2Orta = <(String, String, List<String>, String)>[
  ('Emeviler döneminde Maveraünnehir\'de Buhara, Semerkant ve Harezm gibi merkezleri ele geçirerek bölgede kalıcı Arap egemenliği kurmaya çalışan Horasan valisi kimdir?', 'Kuteybe bin Müslim', ['Ziyad bin Salih', 'Ebu Müslim Horasani', 'Haccac bin Yusuf'], 'Kuteybe bin Müslim 705-715 yılları arasında Maveraünnehir\'de geniş fetihler yaptı; ancak sert tutumu Türklerin tepkisini artırdı.'),
  ('Sulu Kağan önderliğinde Emevi ordularına karşı Maveraünnehir\'de etkili bir direniş gösteren Türk topluluğu hangisidir?', 'Türgişler', ['Oğuz Yabguları', 'Uygurlar', 'Kırgızlar'], 'Türgiş hükümdarı Sulu Kağan 8. yüzyılın ilk yarısında Arap ilerleyişini uzun süre durdurdu; Araplar ona \'Ebu Müzahim\' (süsen boğa) adını verdi.'),
  ('Bir tarihçi \'Talas Savaşı, Türklerin kültür dünyasında yönünü belirleyen bir dönüm noktasıdır.\' diyor. Bu yargıyı en iyi destekleyen gelişme hangisidir?', 'Türk-Arap ilişkilerinin dostluğa dönüşüp İslam\'ın yayılması', ['Türklerin Budizm\'i bütün boylarda resmî din olarak benimsemesi', 'Uygurların Maniheizm\'i kabul etmesi', 'Türklerin Bizans ile ittifak kurması'], 'Savaşta Türklerin Araplarla aynı safta yer alması, iki toplum arasındaki düşmanlığı azalttı ve Türklerin İslamiyet\'i kabulüne zemin hazırladı.'),
  ('Türklerin İslamiyet\'i kabul etmesini kolaylaştıran etkenlerden biri, eski Türk inancı ile İslam arasındaki benzerliklerdir. Aşağıdakilerden hangisi bu benzerliklere örnek olarak gösterilemez?', 'Çok tanrılı bir inanç sisteminin bulunması', ['Tek yaratıcıya inanılması', 'Ölümden sonra hayata inanılması', 'Cennet ve cehennem benzeri kavramların bulunması'], 'Gök Tanrı inancı tek tanrılı bir yapıya sahipti; çok tanrıcılık her iki inanç sisteminde de benzerlik oluşturmaz.'),
  ('Türklerde \'cihat\' anlayışının eski \'cihan hâkimiyeti\' ülküsüyle örtüşmesi, Türklerin İslamiyet\'i kabulünü nasıl etkilemiştir?', 'İslam\'ı yayma görevini kendi siyasi ülküleriyle bütünleştirmelerini sağlamıştır', ['Türklerin göçebe yaşamı bırakıp tamamen şehirlerde yaşamaya başlamasına yol açmıştır', 'Türklerin Arap halifelerine vergi ödemesini zorunlu kılmıştır', 'Türklerin Bizans\'la barış yapmasını kolaylaştırmıştır'], 'Gaza ve cihat anlayışı, Türklerin evrensel hâkimiyet düşüncesiyle birleşti; Türkler İslam\'ın sancaktarlığını üstlendi.'),
  ('Türklerin İslamiyet\'i kabulünün sonuçları arasında aşağıdakilerden hangisi yer almaz?', 'Türklerin Orta Asya dışına hiç göç etmemesi', ['Arap alfabesinin kullanılmaya başlanması', 'Edebiyatta Arapça ve Farsça etkisinin artması', 'Türklerin İslam dünyasının koruyuculuğunu üstlenmesi'], 'İslamiyet\'i kabulden sonra Türkler batıya doğru büyük göçler yaptı ve Anadolu\'ya kadar ulaştı; bu nedenle ilk seçenek yanlış bir yargıdır.'),
  ('Tolunoğulları Devleti\'nin Mısır\'ın yanı sıra hâkimiyet alanına kattığı başlıca bölge hangisidir?', 'Suriye', ['Horasan', 'Maveraünnehir', 'Endülüs'], 'Ahmed bin Tolun Suriye\'yi de ele geçirerek Bizans sınırına kadar uzanan bir egemenlik alanı kurdu.'),
  ('Kahire\'de bugün de ayakta olan ve Samarra mimarisini andıran sarmal minaresiyle bilinen, Tolunoğulları döneminden kalma yapı hangisidir?', 'İbn Tolun Camii', ['Ezher Camii', 'Sultan Hasan Camii', 'Kalavun Külliyesi'], '876-879 yıllarında yaptırılan İbn Tolun Camii\'nin minaresi, Samarra Ulu Camii\'nin sarmal minaresinden etkilenmiştir.'),
  ('Tolunoğulları döneminde Mısır\'da sulama kanallarının onarılması ve tarımın gelişmesi ekonomiye nasıl yansımıştır?', 'Vergi gelirleri artmış ve hazine güçlenmiştir', ['Mısır vergi ve asker bakımından Abbasilere daha bağımlı hâle gelmiştir', 'Nüfusun büyük bölümü şehirleri terk etmiştir', 'Ticaret yolları Mısır dışına kaymıştır'], 'Tarımsal üretimin artması vergileri yükseltti; Ahmed bin Tolun güçlü bir ordu ve büyük bir hazine oluşturabildi.'),
  ('Tolunoğulları Devleti 905 yılında hangi güç tarafından ortadan kaldırılmıştır?', 'Abbasiler', ['Fatımiler', 'Bizanslılar', 'Gazneliler'], 'Ahmed bin Tolun\'un ölümünden sonra zayıflayan devlet, 905\'te Abbasi ordusunun Mısır\'ı yeniden ele geçirmesiyle sona erdi.'),
  ('İhşidi Devleti 969 yılında hangi devletin Mısır\'ı ele geçirmesiyle yıkılmıştır?', 'Fatımiler', ['Abbasiler', 'Eyyubiler', 'Hamdaniler'], 'Kuzey Afrika\'da kurulan Şii Fatımi Devleti 969\'da Mısır\'ı aldı ve Kahire\'yi kurarak İhşidilere son verdi.'),
  ('Tolunoğulları ve İhşidilerin kısa ömürlü olmalarının ortak nedeni olarak aşağıdakilerden hangisi gösterilebilir?', 'Türk nüfusun az olması nedeniyle askerî güce dayanmaları', ['Haçlı seferleriyle sürekli uğraşmak zorunda kalıp yıpranmaları', 'Moğol istilasına uğramaları', 'Bizans\'a bağımlı olarak kurulmaları'], 'Her iki devlet de yerel halkla kaynaşamamış, sınırlı sayıdaki Türk askerine dayanmıştı; bu durum devletlerin uzun ömürlü olmasını engelledi.'),
  ('İlk Müslüman Türk devleti olarak kabul edilen Karahanlıların kuruluşunda hangi Türk boylarının önemli payı vardır?', 'Karluk, Yağma ve Çiğil boyları', ['Kınık, Kayı ve Bayat boyları', 'Kıpçak, Kuman ve Peçenek boyları', 'Oğuz, Uygur ve Kırgız boyları'], 'Karahanlı Devleti, Karluk boylarının önderliğinde Yağma ve Çiğil boylarının katılımıyla kuruldu.'),
  ('Karahanlılarda doğu kolunun başkenti Balasagun ve Kaşgar iken batı kolunun merkezi hangi şehirdir?', 'Semerkant', ['Gazne', 'Taşkent', 'Nişabur'], 'Devlet 1042\'de ikiye ayrıldı; Doğu Karahanlılar Balasagun-Kaşgar, Batı Karahanlılar ise Semerkant merkezli yönetildi.'),
  ('Divanü Lügati\'t-Türk\'ün içinde yer alan ve Türklerin yaşadığı bölgeleri gösteren ilk Türk haritası olarak kabul edilen çizim ne tür bir haritadır?', 'Dünya haritası', ['Deniz haritası', 'Gökyüzü (yıldız) haritası', 'Şehir planı'], 'Kaşgarlı Mahmut eserinde, Türk boylarının yerleşimlerini gösteren yuvarlak bir dünya haritası çizmiştir; merkezde Balasagun bulunur.'),
  ('Divanü Lügati\'t-Türk\'te sözlüğün yanı sıra yer alan atasözleri, şiirler ve boylar hakkındaki bilgiler, esere hangi niteliği kazandırır?', 'Türk kültürünün ansiklopedik kaynağı olma', ['Yalnızca dil bilgisi kurallarını öğreten bir kitap olma', 'Dinî bir tefsir niteliği', 'Hükümdarlara öğüt veren siyasetname'], 'Eser kelimelerin yanında halk edebiyatı örnekleri, gelenekler ve coğrafi bilgiler içerdiği için Türk kültürünün ansiklopedisi sayılır.'),
  ('Ahmet Yesevi\'nin şiirlerinde hece ölçüsü ve sade Türkçe kullanmasının temel nedeni ne olabilir?', 'Mesajını geniş Türk halk kitlelerine ulaştırmak', ['Saray şairleriyle yarışıp hükümdarın beğenisini kazanmak', 'Arap edebiyatını taklit etmek', 'Fars dilini yaygınlaştırmak'], 'Yesevi halkın anlayacağı dil ve ölçüyü seçerek tasavvufi düşüncenin kırsal ve göçebe Türkler arasında yayılmasını sağladı.'),
  ('Gazneli Devleti\'nin asıl kurucusu sayılan ve Samanoğullarından fiilî bağımsızlığı sağlayan hükümdar kimdir?', 'Sebük Tegin', ['Alp Tegin', 'Gazneli Mesud', 'İbrahim'], 'Sebük Tegin 977\'de Gazne\'nin yönetimini ele geçirdi, devleti güçlendirdi ve Hindistan\'a ilk seferleri başlattı.'),
  ('Gazneli Mahmut\'un 1025-1026\'da yağmaladığı ve Hindular için kutsal sayılan ünlü tapınak hangisidir?', 'Somnath', ['Angkor Vat', 'Borobudur', 'Taç Mahal'], 'Gücerat\'taki Somnath tapınağına düzenlenen sefer, Gazneli Mahmut\'un en ünlü Hindistan seferidir.'),
  ('Gazneli Mahmut\'un Şii Büveyhoğullarına karşı seferler düzenlemesi ve Batınileri takip etmesi, onun hangi politikayı izlediğini gösterir?', 'Sünni İslam\'ı ve Abbasi halifeliğini koruma', ['Şii Büveyhoğullarıyla birleşip Şiiliği devlet mezhebi yapma', 'Bizans\'la ittifak kurma', 'Halifeliği Gazne\'ye taşıma'], 'Gazneli Mahmut kendisini Sünni İslam\'ın ve halifeliğin koruyucusu olarak gördü; Rey\'i alarak Büveyhilere ağır bir darbe vurdu.'),
  ('Gazneli Mahmut\'un Hindistan seferlerine katılarak Hint kültürünü, dinlerini ve bilimini anlatan \'Tahkik mâ li\'l-Hind\' adlı eseri yazan bilgin kimdir?', 'Biruni', ['İbn Sina', 'Farabi', 'Utbi'], 'Biruni Sanskrit öğrenerek Hindistan\'ı yerinde inceledi; eseri bu bölge hakkındaki en değerli Orta Çağ kaynaklarındandır.'),
  ('Gazneli Devleti\'nde, Selçuklulardan farklı olarak ordunun büyük kısmını hangi unsur oluşturuyordu?', 'Satın alınan ve yetiştirilen gulam askerler', ['Gönüllü Türkmen aşiret savaşçıları ve boy beyleri', 'İkta sahibi sipahiler', 'Bizans\'tan gelen paralı askerler'], 'Gazneli ordusu büyük ölçüde gulamlardan ve farklı milletlerden oluşan profesyonel askerlerden kuruluydu; Türkmen boy desteği sınırlıydı.'),
  ('Çağrı Bey\'in 1018-1021 yıllarında Doğu Anadolu\'ya yaptığı keşif akını hangi sonucu doğurmuştur?', 'Anadolu\'nun Türkmenler için yurt olabileceğini göstermiştir', ['Bizans\'ın Anadolu\'dan çekilmesini sağlamıştır', 'Ermeni Krallığı\'nın Selçuklulara bağlanıp vergi vermesini sağlamıştır', 'Gaznelilerin Anadolu\'ya yönelmesine yol açmıştır'], 'Çağrı Bey\'in akını, Bizans sınırlarının zayıf olduğunu ve Anadolu\'nun yeni bir Türk yurdu olabileceğini ortaya koydu.'),
  ('Dandanakan Savaşı\'ndan sonra toplanan kurultayda Tuğrul Bey\'in sultan seçilmesi, Selçuklu yönetim anlayışında hangi eski Türk geleneğinin sürdüğünü gösterir?', 'Önemli kararların kurultayda alınması', ['Ülkenin sultanın kişisel malı sayılması', 'Hükümdarın halife tarafından atanması', 'Tahtın her zaman en küçük oğla geçmesi'], 'Kurultay eski Türk devletlerinde de devlet işlerinin görüşüldüğü meclisti; Selçuklular bu geleneği sürdürdü.'),
  ('Selçuklular ile Bizans arasında yapılan ilk büyük savaş olan Pasinler Savaşı hangi yılda gerçekleşmiştir?', '1048', ['1040', '1055', '1071'], 'Pasinler (Hasankale) Savaşı 1048\'de yapıldı; İbrahim Yinal ve Kutalmış komutasındaki Selçuklular Bizans ve Gürcü ordusunu yendi.'),
  ('Pasinler Savaşı\'nın sonuçlarından biri aşağıdakilerden hangisidir?', 'Bizans\'ın Selçuklulara barış için elçi göndermesi', ['Bizans\'ın Anadolu\'daki bütün topraklarını Selçuklulara bırakması', 'İstanbul\'un Selçuklularca kuşatılması', 'Malazgirt\'in Bizans\'a bırakılması'], 'Savaşta Gürcü prensi Liparit esir düştü; Bizans barış istedi ve İstanbul\'daki caminin onarılmasına izin verdi.'),
  ('Tuğrul Bey\'in Abbasi halifesinin kızıyla evlenmesi, dönemin İslam dünyasında neyin göstergesi sayılmıştır?', 'Selçuklu sultanının halifeyle eşit itibar kazanmasının', ['Selçukluların Şiiliği benimseyip Fatımilere yaklaşmasının', 'Halifeliğin Selçuklu hanedanına geçmesinin', 'Abbasilerin Selçuklulara savaş açmasının'], 'Bir Türk sultanının halife ailesiyle evlilik bağı kurması, Selçukluların İslam dünyasındaki prestijini açıkça yükseltti.'),
  ('Alparslan tahta geçtikten sonra taht mücadelesine giriştiği ve 1064\'te yendiği Selçuklu ailesi mensubu kimdir?', 'Kutalmış', ['İbrahim Yinal', 'Kavurt', 'Süleyman Şah'], 'Arslan Yabgu\'nun oğlu Kutalmış taht üzerinde hak iddia etti; Alparslan onu yenerek tahtını sağlamlaştırdı.'),
  ('Alparslan\'ın 1064\'te ele geçirdiği ve Bagratlı Ermeni Krallığı\'nın merkezi olan şehir hangisidir?', 'Ani', ['Kars', 'Van', 'Ahlat'], 'Alparslan 1064\'te Ani\'yi fethetti; şehirdeki katedral camiye çevrildi ve Selçuklular Kafkasya\'da güçlendi.'),
  ('Alparslan\'ın Malazgirt Savaşı öncesinde Suriye\'de bulunmasının ana nedeni neydi?', 'Fatımilere karşı Mısır seferi hazırlığı', ['Haçlılara karşı Kudüs\'ü ve kıyı şehirlerini savunmak', 'Gürcüleri cezalandırmak', 'Karahanlılarla barış yapmak'], 'Alparslan Fatımi Devleti\'ni ortadan kaldırmayı hedefliyordu; Romen Diyojen\'in hareketi üzerine seferi yarıda bırakarak doğuya döndü.'),
  ('Malazgirt Savaşı sırasında Bizans ordusundaki Uz ve Peçenek askerlerinin Selçuklu tarafına geçmesi aşağıdakilerden hangisini kanıtlar?', 'Soydaşlık bağının savaşın gidişini etkilediğini', ['Bizans ordusunun tamamen Türk kökenli askerlerden oluştuğunu', 'Selçukluların paralı asker kullandığını', 'Peçeneklerin Müslüman olduğunu'], 'Bizans ordusundaki Türk kökenli unsurlar savaş sırasında soydaşlarının safına geçti ve bu durum Bizans\'ı zayıflattı.'),
  ('Malazgirt Savaşı\'ndan sonra Alparslan ile Romen Diyojen arasında yapılan antlaşmaya göre aşağıdakilerden hangisi kararlaştırılmamıştır?', 'Bizans başkentinin Selçuklulara teslim edilmesi', ['Bizans\'ın yıllık vergi ödemesi', 'Esir düşen Müslümanların tamamının derhâl serbest bırakılması', 'Bizans\'ın gerektiğinde asker yardımı yapması'], 'Antlaşmada fidye, yıllık vergi, esirlerin serbest bırakılması ve askerî yardım gibi şartlar vardı; İstanbul\'un teslimi söz konusu değildi.'),
  ('Alparslan 1072\'de hangi bölgeye yaptığı sefer sırasında esir bir kale komutanı tarafından yaralanarak ölmüştür?', 'Maveraünnehir (Karahanlılar üzerine)', ['Suriye (Fatımiler üzerine)', 'Anadolu (Bizans üzerine)', 'Kafkasya (Gürcü ve Abhaz kralları üzerine)'], 'Alparslan Karahanlılara karşı Maveraünnehir\'e sefer ederken Berzem Kalesi komutanı Yusuf el-Harezmi tarafından hançerlenerek öldürüldü.'),
  ('Melikşah döneminde Selçuklu ordusunun Kafkasya, Suriye ve Hicaz\'a kadar ulaşması ile Karahanlıların bağlanması birlikte düşünüldüğünde devletin hangi özelliği öne çıkar?', 'Geniş bir coğrafyada siyasi birliği sağlamış olması', ['Yalnızca İran merkezli, sınırları dar küçük bir devlet olması', 'Halifeliği kendi hanedanına geçirmesi', 'Bizans\'a vergi ödeyen bir devlet olması'], 'Melikşah döneminde Türk-İslam dünyasının büyük kısmı tek bir otorite altında toplanmış, siyasi birlik sağlanmıştır.'),
  ('Siyasetname\'de devlet görevlilerinin sık sık denetlenmesini, haberci ve casus teşkilatının güçlü tutulmasını öğütleyen Nizamülmülk\'ün bu önerisi hangi amaca yöneliktir?', 'Haksızlıkları önleyip merkezî otoriteyi korumak', ['Vergi oranlarını sürekli artırarak hazineyi doldurmak', 'Halifenin yetkilerini genişletmek', 'Ordunun sayısını azaltmak'], 'Nizamülmülk, adaletin sağlanmasını ve devletin ayakta kalmasını memurların denetimine bağlamıştır.'),
  ('Batınilerin Selçuklu devlet adamlarına yönelik suikastlerinin temel siyasi hedefi neydi?', 'Sünni Selçuklu otoritesini sarsmak', ['Bizans\'ı Anadolu\'dan çıkarmak', 'Abbasi halifeliğini güçlendirmek', 'Haçlıları Kudüs\'ten ve kıyı şehirlerinden çıkarmak'], 'Batıniler Fatımi propagandasının bir kolu olarak Sünni Selçuklu yönetimine karşı suikast ve terör yöntemini kullandı.'),
  ('Melikşah\'tan sonra tahta geçen ve saltanatı boyunca kardeşleriyle taht mücadelesi yapan Selçuklu sultanı kimdir?', 'Berkyaruk', ['Sencer', 'Tapar\'ın oğlu Mahmud', 'Alparslan'], 'Berkyaruk (1092-1104) döneminde kardeşi Muhammed Tapar ile uzun taht kavgaları yaşandı; bu durum Haçlılara karşı Selçukluları zayıf bıraktı.'),
  ('Katvan Savaşı\'ndaki Müslüman Türk yenilgisinin Avrupa\'da \'Doğuda Hristiyanlara yardım edecek Papaz Yohannes\' efsanesini doğurması neyi gösterir?', 'Haçlı dünyasının Doğu\'daki gelişmeleri kendi lehine yorumladığını', ['Karahıtayların Hristiyanlığı resmî din olarak kabul etmiş bir devlet olduğunu', 'Sencer\'in Haçlılarla ittifak kurduğunu', 'Bizans\'ın Karahıtaylara ordu gönderdiğini'], 'Avrupa\'da Müslümanları yenen doğulu bir Hristiyan kral söylentisi yayıldı; bu efsane gerçeğe dayanmayan bir umudun ürünüydü.'),
  ('Sultan Sencer\'in 1153\'te esir düşmesine neden olan olay hangisidir?', 'Balh bölgesindeki Oğuz Türkmenlerinin ayaklanması', ['Batınilerin Merv\'i uzun süre kuşatıp ele geçirmesi', 'Haçlıların Horasan\'a girmesi', 'Gaznelilerin Nişabur\'u alması'], 'Vergi memurlarının kötü davranışlarına tepki gösteren Oğuzlar ayaklandı; Sencer yenilip yaklaşık üç yıl esir kaldı.'),
  ('Melikşah\'tan sonra merkezî otoritenin zayıflamasıyla atabeyliklerin bağımsız devletlere dönüşmesi, atabeylik kurumu hakkında hangi değerlendirmeyi destekler?', 'Merkez güçlüyken yararlı, zayıfken bölücü bir kurum olmuştur', ['Atabeylik kurumu devletin bütünlüğünü her koşulda ve her dönemde başarıyla korumuştur', 'Atabeylerin hiçbir siyasi yetkisi bulunmamıştır', 'Atabeylik yalnızca Gaznelilerde uygulanmıştır'], 'Atabeyler zamanla yetiştirdikleri meliklerin yerine geçerek bağımsızlaştı; bu durum Selçuklu ülkesinin parçalanmasına katkıda bulundu.'),
  ('Büyük Selçuklularda devlet işlerinin görüşüldüğü ve vezirin başkanlık ettiği kuruma ne ad verilirdi?', 'Divan-ı Saltanat', ['Divan-ı Arz', 'Divan-ı İstifa', 'Divan-ı Tuğra'], 'Büyük Divan da denilen Divan-ı Saltanat\'a vezir başkanlık eder; diğer divanlar ona bağlı çalışırdı.'),
  ('Selçuklularda devlet görevlilerini ve mali işleri denetleyen, bugünkü teftiş kuruluna benzeyen divan hangisidir?', 'Divan-ı İşraf', ['Divan-ı İstifa', 'Divan-ı Arz', 'Divan-ı Mezalim'], 'Divan-ı İşraf\'ın başındaki \'müşrif-i memalik\' devlet işlerini ve görevlileri denetlerdi.'),
  ('Selçuklularda devletin iç ve dış yazışmalarını yürüten ve fermanlara sultanın tuğrasını çeken divan hangisidir?', 'Divan-ı Tuğra (İnşa)', ['Divan-ı Arz', 'Divan-ı İşraf', 'Divan-ı İstifa (Maliye)'], 'Divan-ı Tuğra\'nın başında tuğrai bulunurdu; tuğra bir yay ve oktan oluşan, hükümdarın imzası niteliğindeki işaretti.'),
  ('Selçuklularda sultanın hâkimiyet sembolleri arasında aşağıdakilerden hangisi yer almaz?', 'Halifelik hırkası', ['Cuma hutbesinde ad okutmak', 'Sikke', 'Nevbet'], 'Hutbe okutmak, para bastırmak, nevbet (davul çaldırma), tuğra, çetr ve otağ hükümdarlık sembolleriydi; hırka halifeliğe ait bir semboldü.'),
  ('İkta sisteminin uygulanmasıyla Selçuklu Devleti aşağıdakilerden hangisini sağlamamıştır?', 'Toprağın mülkiyetini ikta sahiplerine devretmeyi', ['Hazineden para harcamadan ordu beslemeyi', 'Tarımsal üretimin sürekliliğini korumayı', 'Göçebe Türkmenlerin yerleşik hayata geçmesini kolaylaştırmayı'], 'İktada toprak devletin malı olarak kalırdı; ikta sahibi yalnızca gelirden yararlanırdı.'),
  ('Nizamiye medreselerinin kurulmasındaki temel amaçlardan biri aşağıdakilerden hangisidir?', 'Sünni düşünceyi güçlendirip Şii-Batıni propagandaya karşı koymak', ['Halifeliği Abbasi ailesinden alıp Selçuklu hanedanına geçirmek ve yaymak', 'Bizans\'la kültürel birlik kurmak', 'Türkçeyi resmî bilim dili yapmak'], 'Medreseler devlete nitelikli memur yetiştirmek ve Fatımi-Batıni propagandasına karşı Sünni düşünceyi yaymak amacıyla kuruldu.'),
  ('Bağdat Nizamiye Medresesi\'nde müderrislik yapan ve \'Tehafütü\'l-Felasife\' adlı eseriyle tanınan bilgin kimdir?', 'İmam Gazali', ['İbn Rüşd', 'Farabi', 'Fahreddin Razi'], 'İmam Gazali 1091\'de Bağdat Nizamiyesi\'ne müderris oldu; filozofları eleştirdiği Tehafütü\'l-Felasife\'yi yazdı.'),
  ('Nizamiye medreselerinin devlet tarafından kurulup desteklenmesi, eğitim tarihinde hangi yeniliği temsil eder?', 'Eğitimin devletin sorumluluğuna alınması', ['Kadınların da medreselere öğrenci olarak kabul edilmesi', 'Eğitimin tamamen Türkçe yapılması', 'Dinî bilimlerin müfredattan çıkarılması'], 'Nizamiyeler, devletin planlı ve sistemli şekilde desteklediği ilk yükseköğretim kurumları arasında sayılır.'),
  ('Suriye Selçuklularının kurucusu olan ve Melikşah\'ın kardeşi olan Selçuklu meliki kimdir?', 'Tutuş', ['Kavurt', 'Süleyman Şah', 'Kutalmış'], 'Tutuş 1078\'de Suriye\'ye gönderildi ve Dımaşk merkezli Suriye Selçuklularını kurdu.'),
  ('İmadeddin Zengi\'nin oğlu olan, Haçlılara karşı Suriye\'de birliği sağlayan ve Mısır\'a Selahaddin\'i gönderen hükümdar kimdir?', 'Nureddin Mahmud Zengi', ['Kutbeddin Mevdud bin Zengi', 'Alaeddin Keykubat', 'Tuğtekin'], 'Nureddin Mahmud Dımaşk\'ı alarak Suriye\'yi birleştirdi; Fatımi Mısır\'ına komutanı Şirkuh ve yeğeni Selahaddin\'i gönderdi.'),
  ('Fars bölgesinde (Şiraz) hüküm süren ve Moğol istilası sırasında barışçı bir politika izleyerek bölgeyi yıkımdan koruyan Türk atabeyliği hangisidir?', 'Salgurlular', ['İldenizliler', 'Böriler', 'Zengiler'], 'Salgurlu atabeyleri Moğollara bağlılık bildirerek Şiraz\'ı korudu; Sadi Şirazi Gülistan ve Bostan\'ı Salgurlu atabeyine ithaf etti.'),
  ('Harzemşahlar Devleti\'nin kurucusu Anuştegin hangi devletin hizmetinde bulunan bir Türk komutandı?', 'Büyük Selçuklu Devleti', ['Gazneli Devleti\'nin sarayı', 'Karahanlı Devleti', 'Abbasi Halifeliği'], 'Anuştegin, Selçuklu sarayında yetişmiş bir gulamdı ve Melikşah döneminde Harezm valiliğine atandı.'),
  ('Harzemşahların en geniş sınırlara ulaştığı ve kendisini \'İkinci İskender\' olarak tanıtan hükümdar kimdir?', 'Alaeddin Muhammed', ['Celaleddin Mengüberti', 'Atsız', 'Tekiş'], 'Alaeddin Muhammed Gurluları ve Karahanlıları ortadan kaldırarak devleti doruğa ulaştırdı; ancak Moğollara karşı başarısız oldu.'),
  ('Yassıçemen Savaşı\'nın Anadolu açısından olumsuz sonucu olarak gösterilen gelişme aşağıdakilerden hangisidir?', 'Moğollarla Anadolu arasındaki tampon gücün ortadan kalkması', ['Anadolu Selçuklularının Haçlılara yenilip batıda toprak kaybetmesi', 'Bizans\'ın Konya\'yı ele geçirmesi', 'Türkmenlerin Anadolu\'dan göç etmesi'], 'Harzemşahların zayıflaması, Moğolların Anadolu sınırlarına dayanmasını kolaylaştırdı; Celaleddin kısa süre sonra öldü.'),
  ('Harzemşahların Moğollara karşı başarısız olmasında aşağıdakilerden hangisi etkili olmamıştır?', 'Halifeliğin Harzemşahlara tam destek vermesi', ['Alaeddin Muhammed\'in ordusunu şehirlere dağıtması', 'Ordudaki Kıpçak komutanlarla saray arasındaki anlaşmazlıklar', 'Moğolların disiplinli ve kalabalık ordusu'], 'Abbasi halifesi Nasır, Harzemşahlarla düşmanca ilişkiler içindeydi; halifenin tam desteği söz konusu değildi.'),
  ('Danişment Gazi\'nin kahramanlıklarını anlatan ve Anadolu\'nun fethini konu alan destani eser hangisidir?', 'Danişmendname', ['Battalname', 'Saltukname', 'Dede Korkut Kitabı'], 'Danişmendname, Danişment Gazi ve arkadaşlarının Anadolu\'daki gaza hikâyelerini anlatır.'),
  ('Saltuklular Beyliği\'nin Gürcülere karşı mücadelesi, Doğu Anadolu açısından hangi işlevi görmüştür?', 'Bölgenin Türk yurdu olarak korunmasını sağlamak', ['Haçlıların Kudüs\'e kara yoluyla ulaşmasını kolaylaştırmak', 'Bizans\'ın doğu sınırını güçlendirmek', 'Moğolların Anadolu\'ya girmesini sağlamak'], 'Saltuklular, Kafkasya\'dan gelen Gürcü saldırılarına karşı bir sınır gücü olarak Doğu Anadolu\'nun Türk kalmasına katkıda bulundu.'),
  ('Divriği Darüşşifası\'nın Mengücekli Melike Turan Melek tarafından yaptırılması, Türk-İslam toplumunda kadının konumu hakkında neyi gösterir?', 'Kadınların hayır ve sosyal hizmet kurumları kurabildiğini', ['Kadınların devlet yönetiminde ve toplum hayatında hiç yer almadığını', 'Kadınların yalnızca saray içinde yaşadığını', 'Kadınların mülk edinmesinin yasak olduğunu'], 'Turan Melek\'in darüşşifa yaptırması, kadınların mülk sahibi olup vakıf kurabildiğini ve sosyal hayatta etkili olduğunu gösterir.'),
  ('Çaka Bey\'in Peçeneklerle iş birliği yaparak İstanbul\'u kuşatma planı, onun hangi hedefe yöneldiğini gösterir?', 'Bizans\'ı karadan ve denizden kuşatarak yıkmaya', ['Haçlılarla ittifak kurup onlarla birlikte Kudüs\'e ulaşmaya', 'Anadolu Selçuklularının başkentini almaya', 'Ege adalarını Venediklilere satmaya'], 'Çaka Bey, Peçeneklerle kuzeyden, kendisi de denizden saldırarak İstanbul\'u ele geçirmeyi amaçladı.'),
  ('Çaka Bey\'in planlarının başarısız olmasında aşağıdaki gelişmelerden hangisi etkilidir?', 'Bizans\'ın Peçeneklere karşı Kumanlarla anlaşması', ['Moğolların İzmir\'i ele geçirmesi', 'Danişmentlilerin Çaka Bey\'e arkadan saldırıp İzmir\'i alması', 'Haçlıların İzmir\'i fethetmesi'], 'Bizans, Kumanları Peçeneklere karşı kullanarak 1091\'de Peçenekleri ağır bir yenilgiye uğrattı ve Çaka Bey\'in müttefikini yok etti.'),
  ('Kutalmışoğlu Süleyman Şah\'ın 1075\'te İznik\'i alarak başkent yapması, yeni kurulan devletin hangi yöne öncelik verdiğini gösterir?', 'Batıya, Bizans topraklarına', ['Doğuya, Horasan\'a', 'Güneye, Mısır\'a', 'Kuzeye, Kıpçak bozkırına doğru'], 'İznik İstanbul\'a çok yakındı; bu tercih, Türkiye Selçuklularının Bizans aleyhine batıya ilerleme hedefini gösterir.'),
  ('Süleyman Şah\'ın 1084\'te ele geçirdiği ve Türkiye Selçuklularını Suriye\'deki Selçuklu kollarıyla karşı karşıya getiren önemli şehir hangisidir?', 'Antakya', ['Halep', 'Dımaşk', 'Urfa'], 'Süleyman Şah 1084\'te Antakya\'yı aldı; ardından Halep\'e yönelince Suriye Selçuklu meliki Tutuş ile çatıştı ve 1086\'da öldü.'),
  ('Süleyman Şah\'ın ölümünden sonra oğlu Kılıçarslan\'ın bir süre Büyük Selçuklu sarayında tutulması, iki devlet arasındaki ilişki hakkında neyi gösterir?', 'Büyük Selçukluların Anadolu\'daki kolu denetim altında tutmak istediğini', ['İki devletin hiçbir zaman ilişki kurmadığını', 'Türkiye Selçuklularının o dönemde Büyük Selçukluları fiilen yönettiğini', 'Bizans\'ın iki devleti birleştirdiğini'], 'Melikşah, bağımsızlaşma eğilimi gösteren Anadolu kolunu denetlemek için Kılıçarslan\'ı İsfahan\'da alıkoydu; o ancak Melikşah\'ın ölümünden sonra Anadolu\'ya dönebildi.'),
  ('I. Haçlı Seferi\'nden önce, Piyer l\'Ermit önderliğinde düzenlenen ve Kılıçarslan tarafından İznik yakınlarında dağıtılan sefere ne ad verilir?', 'Halk Haçlı Seferi', ['Çocuklar Haçlı Seferi', 'Kutsal Roma Seferi', 'Şövalyeler Seferi'], '1096\'da disiplinsiz kalabalıklardan oluşan Halk Haçlı Seferi, I. Kılıçarslan tarafından Anadolu\'da kolayca dağıtıldı.'),
  ('I. Haçlı Seferi sırasında Türkiye Selçuklularının İznik\'i ve Batı Anadolu\'nun bir kısmını kaybetmesi, devletin hangi yönde gelişmesine yol açmıştır?', 'İç ve Doğu Anadolu\'ya yönelmesine', ['Ege adalarına yerleşip denizci bir devlete dönüşmesine', 'Balkanlar\'a geçmesine', 'Mısır\'ı ele geçirmesine'], 'Batı Anadolu\'nun Bizans\'a geçmesi, Türkiye Selçuklularını Orta ve Doğu Anadolu\'da genişlemeye yöneltti.'),
  ('Bizans İmparatoru I. Aleksios Komnenos\'un Haçlı Seferleri\'nin başlamasındaki rolü aşağıdakilerden hangisidir?', 'Türklere karşı Batı\'dan yardım istemesi', ['Kudüs\'ü Haçlılara satması', 'Papa ile savaşa girmesi', 'Haçlılara karşı Türklerle ittifak yapması'], 'Anadolu\'daki Türk ilerleyişinden çekinen Aleksios, Papa\'dan paralı asker yardımı istedi; bu talep Haçlı çağrısının zeminlerinden biri oldu.'),
  ('I. Haçlı Seferi sonucunda Doğu Akdeniz\'de kurulan Haçlı devletlerinden biri aşağıdakilerden hangisi değildir?', 'Kıbrıs Krallığı', ['Urfa Kontluğu', 'Antakya Prinkepsliği', 'Kudüs Krallığı'], 'I. Haçlı Seferi sonunda Urfa Kontluğu, Antakya Prinkepsliği, Kudüs Krallığı ve ardından Trablus Kontluğu kuruldu; Kıbrıs Krallığı III. Haçlı Seferi sonrasında ortaya çıktı.'),
  ('Haçlı Seferleri\'nin Avrupa\'ya etkileri arasında aşağıdakilerden hangisi yer almaz?', 'Kilisenin otoritesinin güçlenip sorgulanmaması', ['Feodal beylerin zayıflaması ve krallıkların güçlenmesi', 'İtalyan şehirlerinin ticaretle zenginleşmesi', 'Doğu\'nun bilim ve teknik bilgisinin Avrupa\'ya taşınması'], 'Seferlerin başarısızlığı Papalığa duyulan güveni sarstı; kilisenin otoritesi zayıfladı.'),
  ('Haçlı Seferleri\'nin Türk-İslam dünyasına etkilerinden biri olarak aşağıdakilerden hangisi gösterilebilir?', 'Türklerin batıya ilerleyişinin bir süre yavaşlaması', ['Abbasi halifeliğinin Avrupa\'ya taşınması', 'Türklerin Hristiyanlığı benimsemesi', 'İslam dünyasının siyasi birliğinin kesin olarak sağlanması'], 'Haçlılarla mücadele Türklerin Anadolu\'da batıya ilerlemesini geçici olarak durdurdu ve İslam dünyasını yıprattı.'),
  ('Miryokefalon Savaşı\'nda Bizans ordusunun ağır kayıp vermesinde Selçuklu ordusunun başvurduğu temel yöntem hangisidir?', 'Dar bir dağ geçidinde pusu kurmak', ['Açık bir ovada cepheden karşılık vermek', 'Bizans kalelerini uzun süre kuşatıp aç bırakmak', 'Deniz yoluyla Bizans ordusunun arkasına asker çıkarmak'], 'II. Kılıçarslan, Bizans ordusunu Tzivritze geçidi denilen dar bir boğazda pusuya düşürdü ve dağınık hâldeyken ağır bir yenilgiye uğrattı.'),
  ('Türkiye Selçuklularının Antalya ve Sinop\'u ele geçirmesi devlete hangi açıdan en fazla yarar sağlamıştır?', 'Kuzey-güney ticaret yolunun denetimi', ['Bizans\'ın Anadolu\'daki varlığının tamamen yıkılması', 'Moğol saldırılarının önlenmesi', 'Haçlıların Kudüs\'ten çıkarılması'], 'Karadeniz ile Akdeniz arasındaki ticaret yolu Selçuklu topraklarından geçmeye başladı; gümrük ve transit gelirleri arttı.'),
  ('I. İzzeddin Keykavus döneminde Sivas\'ta yaptırılan ve sultanın türbesinin de bulunduğu yapı hangisidir?', 'Sivas Darüşşifası', ['Gök Medrese', 'Çifte Minareli Medrese', 'Buruciye Medresesi'], 'I. İzzeddin Keykavus Darüşşifası 1217\'de yaptırıldı; tıp eğitimi de verilen bir hastanedir ve sultanın türbesi buradadır.'),
  ('I. Alaeddin Keykubat\'ın Kırım\'daki Sudak\'a deniz aşırı sefer düzenletmesinin temel amacı nedir?', 'Sinop\'tan Kırım\'a uzanan ticaret yolunu güvenceye almak', ['Bizans başkentini Karadeniz üzerinden kuşatmak', 'Moğolları Kırım\'dan çıkarmak', 'Haçlı devletlerine yardım etmek'], 'Selçuklu tüccarlarının Kırım\'da uğradığı saldırılar üzerine yapılan Sudak seferi, Türk tarihinde ilk deniz aşırı seferlerden sayılır.'),
  ('I. Alaeddin Keykubat\'ın Mengüceklilerin Erzincan kolunu ortadan kaldırması ve Ahlat\'ı alması, onun hangi politikayı izlediğini gösterir?', 'Doğu Anadolu\'da Türk siyasi birliğini sağlama', ['Batıda Bizans\'ı tamamen yıkıp İstanbul\'u alma', 'Moğollarla ittifak yapma', 'Halifeliği Konya\'ya taşıma'], 'Alaeddin Keykubat Doğu Anadolu\'daki küçük beylikleri birleştirerek Moğol tehlikesine karşı güçlü bir sınır oluşturmaya çalıştı.'),
  ('Moğol tehlikesine karşı Konya ve Sivas gibi şehirlerin surlarını tahkim ettiren Türkiye Selçuklu sultanı kimdir?', 'I. Alaeddin Keykubat', ['II. Gıyaseddin Keyhüsrev', 'IV. Kılıçarslan', 'III. Gıyaseddin Keyhüsrev'], 'Moğolların batıya ilerlediğini gören Alaeddin Keykubat, şehir surlarını onarıp güçlendirerek savunma önlemleri aldı.'),
  ('I. Alaeddin Keykubat\'ın Moğollardan kaçan Harzemli askerleri doğu sınır bölgelerine yerleştirmesinin amacı ne olabilir?', 'Doğu sınırını savunmak için deneyimli asker kazanmak', ['Harzemşah Devleti\'ni Anadolu\'da yeniden kurmalarına yardım etmek', 'Bizans\'a karşı ittifak yapmak', 'Bu askerleri Mısır\'a göndermek'], 'Yassıçemen sonrası Selçuklu hizmetine giren Harzemliler doğu sınırlarına ikta verilerek yerleştirildi.'),
  ('Babai İsyanı\'nın nedenleri arasında aşağıdakilerden hangisi yer almaz?', 'Moğolların Türkmenleri isyana kışkırtması', ['Türkmenlerin ağır vergilerden şikâyetçi olması', 'Göçebe Türkmenlerin otlak sıkıntısı yaşaması', 'II. Gıyaseddin\'in yönetimdeki zayıflığı ve saray entrikaları'], 'İsyanın kaynağı iç sosyal ve ekonomik sorunlardı; Moğolların isyanı kışkırttığına dair kesin bir bilgi yoktur.'),
  ('Babai İsyanı\'nın bastırılmasında Selçuklu ordusundaki hangi unsurun etkin rol oynaması dikkat çekicidir?', 'Frank (Latin) paralı askerler', ['Moğol yardımcı kuvvetleri', 'Memlük askerleri', 'Bizans imparatorluk muhafızları'], 'İsyan, Selçuklu ordusundaki Frank paralı askerlerin katkısıyla bastırıldı; bu durum devletin Türkmenlerle ilişkisinin bozulduğunu gösterir.'),
  ('Babai İsyanı\'nın Türkiye Selçuklu Devleti\'ne etkisi en doğru biçimde hangisiyle açıklanır?', 'Ordunun yıpranması Moğollar karşısında devleti zayıf düşürmüştür', ['İsyan sonrası devlet Bizans\'ı ortadan kaldırmıştır', 'İsyan sonrası Türkmenler Anadolu\'yu topluca terk ederek doğuya dönmüştür', 'İsyan devletin sınırlarını genişletmiştir'], 'İsyan Selçuklu askerî gücünü yıprattı; üç yıl sonra Kösedağ\'da Moğollara yenilgide bu zayıflık etkili oldu.'),
  ('Memlük Sultanı Baybars\'ın 1277\'de Anadolu\'ya girerek Moğolları yendiği savaş hangisidir?', 'Elbistan Savaşı', ['Ayn Calut Savaşı', 'Kösedağ Savaşı', 'Humus Savaşı'], 'Baybars Elbistan\'da Moğolları yendi ve Kayseri\'ye girdi; ancak Anadolu\'da kalıcı olmadan Mısır\'a döndü.'),
  ('İlhanlıların Anadolu\'yu yönetmek için genel vali ya da emir göndermesi, Türkiye Selçuklu sultanlarının konumu hakkında neyi gösterir?', 'Sultanların yetkilerinin sembolik düzeye inmesi', ['Sultanların İlhanlı ordusunu ve Moğolları yönetmesi', 'Sultanların halife olarak tanınması', 'Sultanların Bizans\'a bağlanması'], 'Anadolu\'daki gerçek yönetim İlhanlı valilerinin elindeydi; Selçuklu sultanları adı var, yetkisi olmayan hükümdarlara dönüştü.'),
  ('İlhanlı valisi Sülemiş\'in ve ardından Timurtaş\'ın Anadolu\'da İlhanlılara karşı ayaklanması, İlhanlıların Anadolu yönetimi için neyi gösterir?', 'Moğol otoritesinin Anadolu\'da sarsıldığını', ['İlhanlıların Anadolu\'yu Bizans\'a bıraktığını', 'Selçuklu sultanlarının güç kazandığını', 'Memlüklerin Anadolu\'yu tamamen fethettiğini'], 'Valilerin isyanları, İlhanlı merkezinin Anadolu\'yu denetlemekte zorlandığını gösterir ve beyliklerin güçlenmesine zemin hazırlar.'),
  ('İlhanlı hükümdarlarından hangisi Müslüman olarak Mahmud adını almış ve İlhanlıların İslamlaşmasında belirleyici olmuştur?', 'Gazan Han', ['Hülagü Han', 'Abaka Han', 'Argun Han'], 'Gazan Han 1295\'te Müslüman oldu; vezir Reşidüddin ile birlikte idari ve mali reformlar yaptı.'),
  ('Türkiye Selçuklularının 1220\'de Venedik ile yaptığı ticaret antlaşmasında Venedikli tüccarlara gümrük indirimi tanınması aşağıdakilerden hangisini kanıtlar?', 'Selçukluların uluslararası ticareti geliştirmeye önem verdiğini', ['Selçukluların ekonomik açıdan Venedik\'e bağımlı bir devlet olduğunu', 'Venedik\'in Anadolu\'yu yönettiğini', 'Selçukluların deniz ticaretini yasakladığını'], 'Gümrük indirimleriyle yabancı tüccarlar çekildi; Selçuklu limanları ve yolları canlandı.'),
  ('Erzurum\'da bulunan ve iki minareli taç kapısıyla tanınan Selçuklu dönemi medresesi hangisidir?', 'Çifte Minareli Medrese', ['Karatay Medresesi', 'Gök Medrese', 'Sırçalı Medrese'], 'Erzurum Çifte Minareli Medrese 13. yüzyılın ikinci yarısında yapılmıştır; aynı adla anılan bir medrese Sivas\'ta da vardır.'),
  ('Selçuklu taç kapılarında yaygın olarak kullanılan ve sarkıt biçimli, petek görünümlü süsleme tekniğine ne ad verilir?', 'Mukarnas', ['Revzen', 'Kündekari', 'Ebru'], 'Mukarnas, taç kapı nişlerinde ve kubbe geçişlerinde kullanılan, kademeli prizmatik bir süslemedir.'),
  ('Kümbetlerin Orta Asya\'daki çadır biçimini hatırlatan yapısı, Türk-İslam mimarisi hakkında hangi yargıyı destekler?', 'Eski Türk geleneklerinin İslami dönem sanatında sürdüğünü', ['Selçukluların Bizans kilise mimarisini aynen taklit ettiğini', 'Kümbetlerin yalnızca dinî ibadet için yapıldığını', 'Türklerin taş işçiliğini bilmediğini'], 'Kümbet biçimi, göçebe yaşamın çadır geleneğinin taş mimaride devam ettiğini gösteren bir örnektir.'),
  ('Kayseri\'de 1206\'da yaptırılan ve Anadolu\'nun en eski tıp eğitim kurumlarından sayılan darüşşifa, kimin adını taşır?', 'Gevher Nesibe', ['Mahperi Hatun', 'Turan Melek', 'Şah Cihan Hatun'], 'I. Gıyaseddin Keyhüsrev, kız kardeşi Gevher Nesibe\'nin vasiyeti üzerine Kayseri\'de darüşşifa ve tıp medresesinden oluşan çifte yapıyı yaptırdı.'),
  ('Bir mimarlık tarihçisi, Selçuklu medreselerinde kapalı avlulu ve açık avlulu planların bulunduğunu belirtiyor. Kapalı avlulu medreselerin özellikle soğuk iklimli bölgelerde tercih edilmesi neyi gösterir?', 'Mimarinin coğrafi koşullara göre uyarlandığını', ['Kapalı avlunun yalnızca süs amacıyla yapıldığını', 'Medreselerin tamamen Bizans planına uyduğunu', 'Soğuk bölgelerde eğitim yapılmadığını'], 'Kubbeli, kapalı avlulu plan sıcaklığı korumak amacıyla iç bölgelerde yaygınlaştı; mimari iklime göre biçimlendi.'),
  ('Mevlana\'nın eserlerini büyük ölçüde Farsça yazmasının nedeni olarak aşağıdakilerden hangisi gösterilebilir?', 'Farsçanın Selçuklu sarayında edebiyat dili olması', ['Türkçenin o dönemde hiçbir alanda yazı dili olarak kullanılmaması', 'Mevlana\'nın İran\'da sürgünde olması', 'Arapçanın yasaklanmış olması'], 'Selçuklu sarayında ve kentli çevrelerde Farsça edebiyat dili olarak yaygındı; bilim dili ise Arapçaydı.'),
  ('Anadolu\'ya gelen dervişlerin ıssız yerlerde zaviyeler kurarak yerleşmesi, Anadolu\'nun Türkleşmesine nasıl katkıda bulunmuştur?', 'Yeni yerleşim yerlerinin oluşmasına ve Türkmenlerin yerleşmesine öncülük etmiştir', ['Türkmenlerin kırsal bölgeleri ve Anadolu\'yu topluca terk etmesine yol açmıştır', 'Bizans\'ın Anadolu\'da güçlenmesini sağlamıştır', 'Şehirlerin boşalmasına yol açmıştır'], 'Zaviyeler çevresinde köyler kuruldu, yollar güvenli hâle geldi ve göçebe Türkmenler yerleşik hayata geçti.'),
  ('Ahi teşkilatının, devlet otoritesinin zayıfladığı dönemlerde şehirlerde güvenliği sağlaması aşağıdakilerden hangisini gösterir?', 'Teşkilatın sosyal ve siyasi rol de üstlendiğini', ['Teşkilatın yalnızca ticaretle uğraşan bir esnaf birliği olduğunu', 'Ahilerin devlete düşman olduğunu', 'Teşkilatın Moğollarca kurulduğunu'], 'Ahiler Kösedağ sonrasında bazı şehirlerde yönetimi fiilen üstlenmiş, güvenlik ve düzeni sağlamıştır.'),
  ('Türkiye Selçuklularında başkent Konya\'da kurulan ve sultan ya da naibi başkanlığında toplanan devlet meclisine ne ad verilirdi?', 'Büyük Divan', ['Kurultay', 'Meclis-i Mebusan', 'Divan-ı Hümayun'], 'Türkiye Selçuklularında Büyük Divan, vezir, pervane, müstevfi ve tuğrai gibi devlet adamlarından oluşurdu.'),
  ('Türkiye Selçuklularında \'naib-i saltanat\' görevlisi hangi durumlarda devleti yönetirdi?', 'Sultan küçük yaşta ya da başkentte değilken', ['Sultan savaştan galip dönüp tören yaptığında', 'Halife Konya\'yı ziyaret ettiğinde', 'Ordu sefere çıkmadığında'], 'Naib-i saltanat sultanın vekili olarak, sultan küçük yaşta olduğunda veya başkentten uzak bulunduğunda devlet işlerini yürütürdü.'),
  ('Türkiye Selçuklu sultanlarının adlarında Keyhüsrev, Keykavus, Keykubat gibi İran destan kahramanlarının adlarını kullanması neyi gösterir?', 'Fars kültürünün saray çevresindeki etkisini', ['Sultanların soy olarak İranlı bir hanedana mensup olduğunu', 'Türkçenin yasaklandığını', 'Selçukluların Zerdüşt olduğunu'], 'Şehname geleneğinden alınan bu adlar, Selçuklu sarayındaki güçlü Fars kültür etkisinin göstergesidir.'),
  ('Memlük Devleti\'nin ilk döneminde hâkim olan ve Kıpçak Türklerinden oluşan Memlüklere, Nil Nehri\'ndeki adada bulunan kışlalarından dolayı ne ad verilmiştir?', 'Bahri Memlükler', ['Burci Memlükler', 'Çerkez Memlükler', 'Kölemen Beyleri'], 'Bahr, Arapçada büyük su anlamındadır; Ravza adasındaki kışlalarından ötürü bu memlüklere Bahri denmiştir.'),
  ('1260\'ta Filistin\'de Moğol ordusunu yenerek Memlüklerin büyük bir zafer kazanmasını sağlayan sultan kimdir?', 'Kutuz', ['Baybars', 'Kalavun', 'Aybek'], 'Ayn Calut Savaşı\'nda Sultan Kutuz komutasındaki Memlük ordusu Kitbuka Noyan\'ı yendi; Baybars da bu savaşta öne çıkan komutanlardandı.'),
  ('Memlük sultanı Baybars\'ın Bağdat\'tan kaçan Abbasi soyundan birini Kahire\'de halife ilan etmesinin amacı nedir?', 'Memlük Devleti\'ne İslam dünyasında meşruiyet kazandırmak', ['Halifeliği tamamen ortadan kaldırmak', 'Moğollarla ittifak kurmak', 'Haçlılara karşı Bizans\'ın askerî desteğini almak'], 'Kahire\'de yaşatılan Abbasi halifeliği, Memlük sultanlarının İslam dünyasındaki itibarını güçlendirdi.'),
  ('Baybars\'ın 1268\'de ele geçirdiği ve Haçlı devletlerinden birine son verdiği şehir hangisidir?', 'Antakya', ['Akka', 'Urfa', 'Trablus'], 'Baybars 1268\'de Antakya\'yı fethederek Antakya Prinkepsliği\'ni ortadan kaldırdı.'),
  ('Memlüklerin Mekke ve Medine\'yi koruma görevini üstlenmesi ve Kahire\'de halifeliği barındırması, devlete hangi açıdan güç kazandırmıştır?', 'Dinî açıdan İslam dünyasında liderlik iddiası', ['Uzak Doğu baharat ticaretinde tam bir tekel kurma', 'Avrupa\'da toprak kazanımı', 'Moğollarla kalıcı ittifak'], 'Haremeyn\'in hizmetkârlığı ve halifeliğin Kahire\'de bulunması Memlükleri Sünni İslam dünyasının önde gelen gücü yaptı.'),
  ('Memlük Devleti\'nde sultanın oğlunun değil, çoğunlukla güçlü bir emirin tahta çıkması aşağıdakilerden hangisini gösterir?', 'Askerî gücün hanedanlık ilkesinin önüne geçtiğini', ['Memlüklerin seçimle başa gelen bir cumhuriyetle yönetildiğini', 'Halifenin sultanı seçtiğini', 'Tahtın kadınlara bırakıldığını'], 'Memlüklerde taht, kurulmuş bir hanedandan çok güçlü emirler arasında el değiştirdi; askerî güç belirleyiciydi.'),
  ('Delhi Türk Sultanlığı\'nın kurucusu olan ve aslen bir Gurlu kumandanı olan memlük kimdir?', 'Kutbeddin Aybek', ['İltutmış', 'Alaeddin Muhammed Halaci', 'Babür'], 'Kutbeddin Aybek 1206\'da Delhi\'de bağımsız sultanlığını ilan etti; bu hanedana \'Köleler Hanedanı\' da denir.'),
  ('Delhi Sultanlığı\'nın Hindistan\'daki uzun süreli hâkimiyeti sırasında Türkçe, Farsça ve yerel dillerin etkileşimiyle oluşan dil hangisidir?', 'Urduca', ['Sanskritçe', 'Tamilce', 'Bengalce'], '\'Urdu\' kelimesi Türkçe \'ordu\' sözcüğünden gelir; dil ordugâhlarda farklı dillerin karışımıyla gelişti.'),
  ('Altın Orda hükümdarı Berke Han\'ın Müslüman olup Memlüklerle ittifak kurması, İlhanlılarla ilişkilerini nasıl etkilemiştir?', 'İki Moğol devleti arasında düşmanlığa yol açmıştır', ['İlhanlılarla birleşip tek bir Moğol devleti oluşturmalarını sağlamıştır', 'İlhanlıların Hristiyan olmasına neden olmuştur', 'İlhanlıların Mısır\'ı almasını kolaylaştırmıştır'], 'Berke Han, Bağdat\'ı yıkan Hülagü\'ye karşı Memlüklerle ittifak yaptı; Kafkasya\'da iki devlet arasında savaşlar yaşandı.'),
  ('Altın Orda Devleti\'nin yıkılmasından sonra ortaya çıkan Türk hanlıklarından biri aşağıdakilerden hangisi değildir?', 'Delhi Sultanlığı', ['Kazan Hanlığı', 'Kırım Hanlığı', 'Astrahan Hanlığı'], 'Kazan, Kırım, Astrahan ve Sibir hanlıkları Altın Orda\'nın parçalanmasıyla kuruldu; Delhi Sultanlığı Hindistan\'da ve daha önce kuruldu.'),
  ('Cengiz Han\'ın oğlu Çağatay\'ın payına düşen ve Maveraünnehir ile Yedisu bölgesini kapsayan hanlıkta zamanla hangi dil yazı dili olarak gelişmiştir?', 'Çağatay Türkçesi', ['Oğuz Türkçesi', 'Moğolca', 'Farsça'], 'Çağatay Hanlığı\'nda Türkleşme sonucu doğu Türk yazı dili gelişti; bu dil sonradan Çağatay Türkçesi adıyla anıldı.'),
  ('Kütahya merkezli kurulan ve 14. yüzyılda Batı Anadolu\'nun en güçlü beyliklerinden biri olan Türkmen beyliği hangisidir?', 'Germiyanoğulları', ['Karesioğulları', 'Candaroğulları', 'Menteşeoğulları'], 'Germiyanoğulları Kütahya\'yı merkez edinmişti; Batı Anadolu\'daki diğer uç beylikleri üzerinde de etkiliydi.'),
  ('Kastamonu ve Sinop çevresinde hüküm süren ve İsfendiyaroğulları olarak da bilinen beylik hangisidir?', 'Candaroğulları', ['Pervaneoğulları', 'Ramazanoğulları', 'Dulkadiroğulları'], 'Candaroğulları Kastamonu ve Sinop\'u merkez edindi; Kötürüm Bayezid ve İsfendiyar Bey dönemleri önemlidir.'),
  ('Muğla ve Milas çevresinde kurulan ve Ege kıyılarında denizcilikle uğraşan beylik hangisidir?', 'Menteşeoğulları', ['Karesioğulları', 'Hamitoğulları', 'Eretnaoğulları'], 'Menteşeoğulları Muğla-Milas yöresinde hüküm sürdü; Rodos şövalyeleriyle mücadele etti.'),
  ('Eretnaoğullarının yerine Sivas\'ta beylik kuran, aynı zamanda şair ve kadı olan Kadı Burhaneddin\'in kurduğu devletin en belirgin özelliği hangisidir?', 'Hükümdarının âlim ve şair kimliği', ['Denizcilikte üstünlüğü', 'Moğollara bağlı bir vilayet olması', 'Hristiyan bir hanedan tarafından yönetilmesi'], 'Kadı Burhaneddin hem hükümdar hem de Türkçe divan sahibi bir şairdi; Timur\'a karşı da direniş gösterdi.'),
  ('Anadolu\'da Türkçeyi resmî dil ilan etmesiyle bilinen beyliğin, Konya\'yı ele geçirme mücadelesi nedeniyle uzun süre çatıştığı güçlerden biri aşağıdakilerden hangisidir?', 'İlhanlılar', ['Abbasiler', 'Gazneliler', 'Karahanlılar'], 'Karamanoğulları Konya\'yı almak için İlhanlılar ve onların Anadolu valileriyle uzun süre mücadele etti.'),
  ('Beylikler döneminde Türkçe eserlerin yazılmasının hızlanması, bu dönem hakkında hangi yargıyı destekler?', 'Türkçenin edebiyat ve bilim dili olarak güçlendiği', ['Arapçanın bilim ve din dili olarak tamamen unutulduğu', 'Farsçanın resmî dil yapıldığı', 'Uygur alfabesine geri dönüldüğü'], 'Beyler, Arapça ve Farsça eserleri Türkçeye çevirtti; halkın anlayacağı dilde yazılmış eserler çoğaldı.'),
  ('Beyşehir\'i merkez edinen ve Beyşehir Eşrefoğlu Camii ile tanınan beylik hangisidir?', 'Eşrefoğulları', ['Hamitoğulları', 'Karamanoğulları', 'Sahip Ataoğulları'], 'Eşrefoğlu Süleyman Bey\'in 1296-1299\'da yaptırdığı ahşap direkli cami, UNESCO Dünya Mirası Listesi\'ndedir.'),
  ('Farabi\'ye \'Muallim-i Sani\' (İkinci Öğretmen) unvanının verilmesinin nedeni aşağıdakilerden hangisidir?', 'Aristoteles\'ten sonra mantık ve felsefede en büyük otorite sayılması', ['İlk Türkçe sözlüğü yazıp Abbasi halifesine sunmuş olması', 'İslam dünyasında ilk medreseyi açması', 'Hindistan\'ı ilk kez inceleyen bilgin olması'], 'Aristoteles \'Birinci Öğretmen\' kabul edilirdi; onun eserlerini yorumlayan Farabi\'ye \'İkinci Öğretmen\' denildi.'),
  ('Farabi\'nin ideal devlet ve toplum düzenini anlattığı eser hangisidir?', 'El-Medinetü\'l-Fazıla', ['El-Kanun fi\'t-Tıb', 'Kitabü\'ş-Şifa', 'Tahkik mâ li\'l-Hind'], 'Farabi\'nin \'Erdemli Şehir\' anlamına gelen eseri, mutluluğa ulaşmış ideal bir toplumu tasvir eder.'),
  ('Farabi\'nin müzik alanındaki çalışmalarıyla ilgili olarak aşağıdakilerden hangisi doğrudur?', 'Müzik kuramı üzerine kapsamlı bir eser yazmıştır', ['Müziği tamamen yasaklayan fetvalar vererek eleştirmiştir', 'Yalnızca askerî marşlar bestelemiştir', 'Müzikle hiç ilgilenmemiştir'], 'Farabi\'nin Kitabü\'l-Musika\'l-Kebir\'i İslam dünyasında müzik teorisinin temel eserlerindendir.'),
  ('Harezmi\'nin Hint rakamlarını ve sıfırı tanıtan eserlerinin Latinceye çevrilmesi Avrupa\'da hangi gelişmeye katkıda bulunmuştur?', 'Roma rakamları yerine onluk konumsal sistemin yaygınlaşmasına', ['Takvimin güneş yılı yerine ay yılına göre düzenlenmesine', 'Matbaanın icat edilmesine', 'Barutun kullanılmaya başlanmasına'], 'Harezmi\'nin aritmetik eserleri sayesinde Avrupa\'da sıfır ve onluk sayı sistemi yayıldı; hesaplamalar kolaylaştı.'),
  ('Biruni\'nin Dünya\'nın çevresini ölçmek için kullandığı yöntem aşağıdakilerden hangisine dayanır?', 'Bir dağın yüksekliği ile ufuk çizgisinin eğim açısına', ['Gölgelerin yalnızca gün ortasında farklı şehirlerdeki boyuna', 'Gemi yolculuğunun süresine', 'Ay tutulmasının süresine'], 'Biruni, Nandana yakınlarında bir dağın yüksekliğini ve ufkun alçalma açısını ölçerek trigonometriyle Dünya\'nın yarıçapını hesapladı.'),
  ('Gazneli sarayında bulunan bilginlerden Biruni\'nin bilim tarihine katkıları arasında aşağıdakilerden hangisi yer almaz?', 'Barutun icadı', ['Dünya\'nın yarıçapını hesaplaması', 'Maddelerin özgül ağırlıklarını ölçmesi', 'Hindistan üzerine kapsamlı bir eser yazması'], 'Biruni astronomi, coğrafya ve fizik alanlarında çalıştı; barutun icadı ise Çin\'e aittir.'),
  ('İbn Sina\'nın Kitabü\'ş-Şifa adlı eserinin adı tıbbı çağrıştırsa da eser asıl olarak hangi alanı kapsar?', 'Felsefe ve doğa bilimleri', ['Yalnızca cerrahi ve ilaç yapımı', 'Fıkıh ve tefsir', 'Divan şiiri'], 'Kitabü\'ş-Şifa mantık, fizik, matematik ve metafizik bölümlerinden oluşan ansiklopedik bir felsefe eseridir; \'ruhun şifası\' anlamı taşır.'),
  ('Selçuklularda şer\'i davalara bakan kadıların başındaki en yüksek yargı görevlisine ne denirdi?', 'Kadı\'l-kudat', ['Emir-i dad', 'Muhtesip', 'Şıhne'], 'Kadı\'l-kudat, başkentte bulunan baş kadıydı; diğer kadıların atanmasında ve denetlenmesinde etkiliydi.'),
  ('Selçuklu sultanının haftanın belirli günlerinde halkın şikâyetlerini bizzat dinlediği yüksek mahkemeye ne ad verilirdi?', 'Divan-ı Mezalim', ['Divan-ı İşraf', 'Divan-ı İstifa', 'Divan-ı Arz'], 'Divan-ı Mezalim, devlet görevlilerinin haksızlıklarına karşı halkın başvurduğu ve sultanın başkanlık ettiği mahkemeydi.'),
  ('Türk-İslam şehirlerinde çarşı ve pazarı denetleyen, ölçü ve tartıları kontrol eden görevliye ne ad verilirdi?', 'Muhtesip', ['Subaşı', 'Kethüda', 'Atabey'], 'Muhtesip, hisbe teşkilatının başındaki görevliydi; fiyatları, ölçüleri ve kamu ahlakını denetlerdi.'),
  ('Türk-İslam devletlerinde hükümdarın \'Tanrı tarafından verilen yönetme yetkisi\' (kut) anlayışının yerini alan meşruiyet kaynağı hangisidir?', 'Halife tarafından onaylanma', ['Bizans imparatorunun tanıması', 'Kurultayın tamamen kaldırılması', 'Halkın oyuyla seçilme'], 'İslamiyet\'ten sonra hükümdarlar meşruiyeti halifenin gönderdiği menşur ve hil\'at ile pekiştirdi.'),
  ('Eski Türk devletlerinde ve Türk-İslam devletlerinde ortak olarak görülen özelliklerden biri aşağıdakilerden hangisidir?', 'Ülkenin hanedan üyelerinin ortak malı sayılması', ['Halifenin hükümdarı onaylaması', 'İkta sisteminin uygulanması', 'Medreselerde eğitim yapılması'], 'Ülkenin hanedanın ortak malı sayılması, eski Türk anlayışından Türk-İslam devletlerine geçen bir gelenektir; diğerleri İslami dönemle ortaya çıkmıştır.'),
  ('Aşağıdaki savaşlardan hangisi Malazgirt Savaşı\'ndan sonra, Kösedağ Savaşı\'ndan önce yapılmıştır?', 'Miryokefalon', ['Pasinler', 'Dandanakan', 'Nesa'], 'Nesa 1035, Dandanakan 1040, Pasinler 1048, Malazgirt 1071, Miryokefalon 1176, Kösedağ 1243 yılındadır; iki savaş arasında yalnız Miryokefalon kalır.'),
  ('Aşağıdaki gelişmelerden hangisi Türkiye Selçuklu sultanı I. Alaeddin Keykubat döneminden önce yaşanmıştır?', 'Antalya\'nın fethi', ['Alanya\'nın fethi', 'Yassıçemen Savaşı', 'Sudak seferi'], 'Antalya 1207\'de I. Gıyaseddin Keyhüsrev döneminde alındı; diğerleri Alaeddin Keykubat dönemindedir.'),
  ('Aşağıdaki eşleştirmelerden hangisi yanlıştır?', 'Celali Takvimi – Alparslan', ['Siyasetname – Nizamülmülk', 'Divan-ı Hikmet – Ahmet Yesevi', 'Mesnevi – Mevlana'], 'Celali Takvimi Melikşah döneminde hazırlanmıştır; Melikşah\'ın unvanı Celaleddin\'di.'),
  ('922 yılında Abbasi halifesine elçi göndererek İslamiyet\'i resmen kabul eden ve İdil Nehri boyunda yaşayan Türk devleti hangisidir?', 'İdil (Volga) Bulgarları', ['Tuna Bulgarları', 'Hazar Kağanlığı', 'Peçenekler Birliği'], 'İdil Bulgar hükümdarı Almış Han halifeden yardım istedi; Abbasi heyeti 922\'de geldi ve İslamiyet resmî din oldu.'),
  ('Abbasi halifesinin İdil Bulgarlarına gönderdiği heyette bulunan ve yolculuk boyunca Oğuzlar, Peçenekler ve Bulgarlar hakkında gözlemlerini yazan seyyah kimdir?', 'İbn Fadlan', ['İbn Battuta', 'İbn Haldun', 'Mesudi'], 'İbn Fadlan Seyahatnamesi, 10. yüzyıl Türk boylarının yaşayışı hakkında birinci elden bilgiler verir.'),
  ('İdil Bulgarlarının İslamiyet\'i kabul etmesinde Hazar Kağanlığı\'nın baskısından kurtulma isteğinin etkili olduğu bilinmektedir. Bu bilgi, din değiştirme kararının hangi yönünü öne çıkarır?', 'Siyasi ve stratejik yönünü', ['Yalnızca ekonomik çıkarı', 'Bizans kilisesine bağlılığı', 'Çin\'in kültürel etkisini'], 'Almış Han halifeyle iş birliği yaparak Yahudi Hazarlara karşı güçlü bir müttefik ve meşruiyet kazanmak istedi.'),
  ('İdil Bulgarları ticarette İskandinavya\'dan gelen tüccarlarla Doğu dünyası arasında aracılık yapmışlardır. Bu durumu en çok hangi coğrafi özellik kolaylaştırmıştır?', 'İdil Nehri\'nin kuzey-güney ticaret yolu olması', ['Akdeniz kıyısında bulunmaları', 'Çöl kervan yollarının merkezinde olmaları', 'Hint Okyanusu\'na açılan limanları'], 'İdil Nehri, kürk ve köle ticaretinde Baltık ile Hazar Denizi\'ni birbirine bağlıyordu; Bulgar şehri bu yolun önemli pazarıydı.'),
  ('İdil Bulgar Devleti\'ne 1236\'da son veren güç aşağıdakilerden hangisidir?', 'Moğollar', ['Ruslar', 'Hazarlar', 'Kumanlar'], 'Batu Han komutasındaki Moğollar 1236\'da Bulgar şehrini yıktı; bölge sonra Altın Orda\'ya katıldı.'),
  ('Uluğ Bey\'in rasathanesinde çalışan ve sonradan İstanbul\'a gelerek matematik ve astronomi öğreten bilgin kimdir?', 'Ali Kuşçu', ['Kadızade-i Rumi', 'Takiyüddin', 'Nasirüddin Tusi'], 'Ali Kuşçu, Uluğ Bey\'in ölümünden sonra Akkoyunlu sarayına, ardından İstanbul\'a geçti.'),
  ('Hüseyin Baykara döneminde Herat\'ta vezirlik yapan ve Muhakemetü\'l-Lügateyn adlı eserinde Türkçenin Farsçadan üstün olduğunu savunan şair kimdir?', 'Ali Şir Nevai', ['Molla Cami', 'Fuzuli', 'Babür'], 'Ali Şir Nevai Çağatay Türkçesinin en büyük şairidir; Muhakemetü\'l-Lügateyn\'de iki dili karşılaştırmıştır.'),
  ('Timurlular döneminde Herat\'ın bilim ve sanat merkezi olması, devletin siyasi gücü zayıflarken kültürel alanda nasıl bir tablo ortaya koyduğunu gösterir?', 'Siyasi zayıflamaya rağmen kültürel parlaklığın sürdüğünü', ['Kültürün siyasetten tamamen koptuğunu', 'Sanatın yalnızca Semerkant\'ta yapıldığını', 'Bilim çalışmalarının yasaklandığını'], 'Hüseyin Baykara döneminde siyasi güç sınırlı olsa da Herat minyatür, şiir ve mimaride parlak bir merkez oldu.'),
  ('Babür\'ün 1526\'da Delhi Sultanı İbrahim Lodi\'yi yenerek Hindistan\'da devletini kurduğu savaş hangisidir?', 'Birinci Panipat Savaşı', ['Talikota Savaşı', 'Plassey Savaşı', 'Haldighati Savaşı'], 'Babür Panipat\'ta topçu ve araba barikatlarını etkili kullanarak Lodi ordusunu yendi.'),
  ('Babür Şah\'ın hayatını ve dönemini Çağatay Türkçesiyle anlattığı anı türündeki eseri hangisidir?', 'Baburname', ['Ekbername', 'Tuzuk-ı Cihangiri', 'Hümayunname'], 'Baburname, Türk edebiyatının ilk otobiyografik eserlerinden sayılır; doğa, şehir ve insan gözlemleriyle doludur.'),
  ('Babür İmparatorluğu\'nun 1858\'de resmen sona ermesinde hangi güç belirleyici olmuştur?', 'İngiltere', ['Fransa', 'Portekiz', 'Hollanda'], '1857 Büyük Hint Ayaklanması\'ndan sonra İngilizler son Babür hükümdarı II. Bahadır Şah\'ı sürgüne gönderdi.'),
  ('Ekber Şah\'ın gayrimüslimlerden alınan cizye vergisini kaldırması, onun yönetim anlayışı hakkında hangi çıkarımı destekler?', 'Farklı inançtaki halkı devlete bağlamaya çalıştığını', ['İslam\'ı yasaklamak istediğini', 'Hindistan\'dan çekilmeyi planladığını', 'Vergi gelirini artırmak istediğini'], 'Nüfusun çoğunluğunun Hindu olduğu bir ülkede Ekber, uzlaşmacı politikalarla tebaasının sadakatini kazanmaya çalıştı.'),
  ('Tebriz\'i başkent yapan ve Cihan Şah döneminde en parlak çağını yaşayan Türkmen devleti hangisidir?', 'Karakoyunlular', ['Akkoyunlular', 'Dulkadiroğulları', 'Ramazanoğulları'], 'Karakoyunlular Kara Yusuf ile güçlendi; Cihan Şah döneminde İran\'ın büyük kısmına hâkim oldular.'),
  ('Akkoyunlu Devleti\'nin ilk merkezi olan ve Dicle kıyısındaki surlarıyla ünlü şehir hangisidir?', 'Diyarbakır', ['Erzurum', 'Van', 'Erzincan'], 'Akkoyunlular Kara Yülük Osman döneminde Diyarbakır\'ı merkez edindi; Uzun Hasan döneminde başkent Tebriz\'e taşındı.'),
  ('Uzun Hasan\'ın Venedik ile yazışarak ateşli silah yardımı istemesi, Akkoyunlu dış politikası hakkında neyi gösterir?', 'Bölgesel rakiplerine karşı Avrupa ile ittifak arayışını', ['Venedik\'e bağlı bir devlet olduğunu', 'Hristiyanlığı kabul etmeyi düşündüğünü', 'Denizcilikte üstünlük kurmak istediğini'], 'Uzun Hasan, güçlü komşularına karşı Venedik ile diplomatik ilişki kurarak ateşli silah elde etmeye çalıştı.'),
  ('Karakoyunlu ve Akkoyunlu devletlerinin adlarını aldıkları \'karakoyun\' ve \'akkoyun\' sözcükleri en yaygın yoruma göre neyi ifade eder?', 'Boy sancaklarındaki ya da totemlerindeki koyun figürlerini', ['Hükümdarlarının giydiği kürk renklerini', 'Başkentlerindeki saray renklerini', 'Ödedikleri verginin miktarını'], 'Kaynaklarda bu adların bayraklarındaki koyun figürleriyle ya da sahip oldukları sürülerin rengiyle ilişkili olduğu belirtilir.'),
  ('Malazgirt\'ten sonra Anadolu\'ya gelen Türkmenlerin köylere, dağlara ve ırmaklara Orta Asya\'daki yer adlarını vermesi neyi gösterir?', 'Anadolu\'yu yeni bir yurt olarak benimsediklerini', ['Anadolu\'da kalıcı olmak istemediklerini', 'Yerel halkı tamamen sürdüklerini', 'Orta Asya\'ya geri dönmeyi planladıklarını'], 'Yer adlarının taşınması, göç eden toplulukların yeni topraklarla bağ kurduğunu ve Anadolu\'nun Türk yurdu hâline geldiğini gösterir.'),
  ('Anadolu\'nun Türkleşmesini kolaylaştıran etkenler arasında aşağıdakilerden hangisi gösterilemez?', 'Bizans\'ın yerli halktan aldığı vergileri azaltması', ['Moğol istilasından kaçan Türkmenlerin gelmesi', 'Dervişlerin kurduğu zaviyeler', 'Türkmenlerin köy ve kasabalara yerleşmesi'], 'Bizans\'ın ağır vergi ve dinî baskıları yerli halkı Türk yönetimini tercih etmeye yöneltmişti; vergi indirimi bir Türkleşme etkeni değildir.'),
  ('Battal Gazi\'nin kahramanlıklarını anlatan ve Anadolu\'da Türk-İslam destan geleneğinin ürünü olan eser hangisidir?', 'Battalname', ['Danişmendname', 'Oğuzname', 'Köroğlu Destanı'], 'Battalname, Emeviler döneminde Bizans\'a karşı savaşan Battal Gazi etrafında oluşmuş, Anadolu\'da Türkçe olarak yaygınlaşmış bir destandır.'),
  ('Selçuklu taş işçiliğinde dikkat çeken çift başlı kartal motifi en çok hangi anlamla yorumlanır?', 'Güç ve egemenlik simgesi', ['Ticaretin bereketi', 'Kış mevsiminin gelişi', 'Ölümün ve yasın işareti'], 'Çift başlı kartal Selçuklu yapılarında, örneğin Divriği\'de, hükümdarlık ve kudreti simgeleyen bir motif olarak kullanıldı.'),
  ('Selçuklu döneminde kitap süsleme sanatlarından olan ve kitap sayfalarının altınla bezenmesine dayanan sanata ne denir?', 'Tezhip', ['Kündekari', 'Hat', 'Kakma'], 'Tezhip \'altınlama\' anlamına gelir; Kur\'an ve el yazması kitapların sayfa kenarları ve başlıkları bu yolla süslenirdi.'),
  ('Divriği Ulu Camii\'nin kapılarında görülen ve neredeyse üç boyutlu bitkisel taş süslemeleri, mimarlık tarihçileri tarafından nasıl değerlendirilir?', 'Anadolu Selçuklu taş işçiliğinin doruk noktası', ['Bizans mozaik geleneğinin kopyası', 'Moğol çadır mimarisinin taşa uyarlanması', 'Fatımi ahşap oymacılığının devamı'], 'Divriği\'nin taç kapıları alışılmışın dışındaki derin, plastik bezemeleriyle eşsiz kabul edilir ve UNESCO listesine girmiştir.'),
  ('Karahanlılar döneminde Türkçe ve İslami unsurları bir arada barındıran Kutadgu Bilig, Divanü Lügati\'t-Türk ve Atabetü\'l-Hakayık\'ın ortak özelliği aşağıdakilerden hangisidir?', 'Türkçe yazılmış olmaları', ['Üçünün de sözlük türünde olması', 'Bağdat\'ta halifeye sunulmaları', 'Farsça yazılıp Türkçeye çevrilmeleri'], 'Divanü Lügati\'t-Türk Arapça açıklamalı olsa da Türkçe sözcük ve metinleri konu alır; üç eser de Türk dilinin İslami dönemdeki ilk büyük ürünleridir.'),
  ('Kaşgarlı Mahmut\'un Divanü Lügati\'t-Türk\'te Oğuz boylarını tek tek sayıp damgalarını vermesi, tarihçiler için hangi açıdan değerlidir?', 'Oğuz boy teşkilatına dair erken ve güvenilir bilgi sunması', ['Oğuzların Arap kökenli olduğunu kanıtlaması', 'Oğuzların Budist olduğunu göstermesi', 'Oğuzların hiç göç etmediğini belgelemesi'], 'Kaşgarlı\'nın verdiği 22 Oğuz boyu ve damgaları, boy teşkilatının bilinen en eski kayıtlarındandır.'),
  ('Gazneli Mahmut\'un ölümünden sonra yerine geçen ve Dandanakan\'da Selçuklulara yenilen oğlu Mesud döneminde Gaznelilerin en büyük sorunu ne olmuştur?', 'Selçukluların Horasan\'da güçlenmesi', ['Haçlıların Gazne\'yi kuşatması', 'Moğolların Hindistan\'ı istila etmesi', 'Abbasilerin Gazne\'ye ordu göndermesi'], 'Mesud döneminde Selçuklular Horasan\'da hızla güçlendi; Nesa ve Dandanakan yenilgileri Gaznelileri batıdan çekilmeye zorladı.'),
  ('Gazneli sarayında Firdevsi\'nin yanı sıra Unsuri gibi Farsça yazan şairlerin bulunması, Gazneli kültür hayatının hangi özelliğine işaret eder?', 'Fars edebiyatının saray himayesinde gelişmesine', ['Türkçenin tek yazı dili olmasına', 'Arapçanın yasaklanmasına', 'Şiirin saraydan dışlanmasına'], 'Gazneli hükümdarları Fars şairlerini himaye etti; Gazne Fars edebiyatının önemli merkezlerinden biri hâline geldi.'),
  ('Gazneliler döneminde Gazne şehrinin Hindistan seferlerinden elde edilen ganimetlerle süslenmesi aşağıdakilerden hangisine yol açmıştır?', 'Gazne\'nin dönemin büyük kültür ve sanat merkezlerinden biri olmasına', ['Gazne\'nin terk edilip başkentin Bağdat\'a taşınmasına', 'Gazne halkının Budizm\'e geçmesine', 'Gazne\'nin Bizans\'a bağlanmasına'], 'Ganimetler cami, medrese ve saray yapımında kullanıldı; bilginler ve sanatçılar Gazne\'de toplandı.'),
  ('Melikşah döneminde Büyük Selçuklu Devleti\'nin başkenti olan ve Mescid-i Cuma\'sı ile Selçuklu mimarisinin önemli eserlerini barındıran şehir hangisidir?', 'İsfahan', ['Rey', 'Nişabur', 'Tebriz'], 'Melikşah İsfahan\'ı başkent yaptı; Nizamülmülk ve Tacülmülk kubbeleri İsfahan Mescid-i Cuma\'sındadır.'),
  ('Melikşah\'ın 1092\'deki ölümü ile Nizamülmülk\'ün aynı yıl öldürülmesi Büyük Selçuklu tarihi açısından neden bir dönüm noktası sayılır?', 'Devletin duraklama ve bölünme sürecine girmesi', ['Devletin en geniş sınırlarına ulaşması', 'Haçlı Seferleri\'nin sona ermesi', 'Halifeliğin Selçuklulara geçmesi'], 'İki güçlü liderin kaybıyla merkezî otorite sarsıldı; taht kavgaları başladı ve devlet bölünmeye yöneldi.'),
  ('Melikşah\'ın eşi Terken Hatun\'un oğlu Mahmud\'u tahta çıkarmak için çabalaması, Selçuklu saray yaşamı hakkında neyi gösterir?', 'Saray kadınlarının siyasette etkili olabildiğini', ['Kadınların sarayda yaşamadığını', 'Tahtın her zaman kızlara geçtiğini', 'Sultanların evlenmediğini'], 'Terken Hatun, küçük yaştaki oğlu Mahmud\'u sultan ilan ettirerek siyasi gücünü gösterdi; bu durum taht kavgalarını şiddetlendirdi.'),
  ('Büyük Selçukluların Türkmenleri Bizans sınırlarına yönlendirmesinin nedenlerinden biri aşağıdakilerden hangisidir?', 'Türkmenlerin yerleşik halkla yaşadığı sorunları azaltmak', ['Türkmenleri Moğollara karşı korumak', 'Türkmenlerin Hristiyan olmasını sağlamak', 'Türkmenleri Mısır\'a yerleştirmek'], 'Göçebe Türkmenlerin İran\'daki tarım alanlarına zarar vermesi sorun yaratıyordu; sınıra yönlendirilmeleri hem bu sorunu çözdü hem fetihleri hızlandırdı.'),
  ('Kudüs\'ün I. Haçlı Seferi\'nden kısa süre önce Fatımilerin eline geçmesi, Haçlıların şehri 1099\'da almasını nasıl etkilemiştir?', 'Haçlılar şehri Selçuklulardan değil Fatımilerden almıştır', ['Haçlılar Kudüs\'e hiç ulaşamamıştır', 'Kudüs Bizans\'ın elinde kalmıştır', 'Selçuklular şehri Haçlılara teslim etmiştir'], 'Artuklulardan Kudüs\'ü 1098\'de alan Fatımiler, ertesi yıl şehri Haçlılara kaptırdı.'),
  ('Fatımi Devleti hangi mezhebi benimseyen ve kendisini halife ilan eden bir devletti?', 'İsmaili Şia', ['Sünni Hanefi', 'Harici', 'Sünni Şafii'], 'Fatımiler İsmaili Şii bir halifelikti; bu nedenle Sünni Abbasi halifeliği ve Selçuklularla rakip oldu.'),
  ('Selçukluların Fatımilere karşı uzun süre mücadele etmesinin temel nedeni aşağıdakilerden hangisidir?', 'Sünni Abbasi halifeliğini Şii rakibine karşı korumak', ['Fatımilerin Bizans\'ın bir eyaleti olması', 'Fatımilerin Oğuz boylarından oluşması', 'Fatımilerin Hint ticaretini engellemesi'], 'Selçuklular kendilerini Sünni İslam\'ın ve Abbasi halifesinin koruyucusu olarak gördü; Fatımiler hem siyasi hem mezhepsel bir tehditti.'),
  ('Türkiye Selçuklu sultanı I. Mesud döneminde düzenlenen ve Anadolu\'dan geçerken Türkler tarafından ağır kayıplara uğratılan Haçlı seferi hangisidir?', 'II. Haçlı Seferi', ['I. Haçlı Seferi', 'III. Haçlı Seferi', 'IV. Haçlı Seferi'], 'Alman Kralı III. Konrad ve Fransa Kralı VII. Louis\'nin orduları 1147-1148\'de Anadolu\'da büyük kayıplar verdi.'),
  ('I. Mesud döneminde Türkiye Selçuklularının Danişmentlilerle ilişkisi hangi süreçten geçmiştir?', 'Başlangıçta Danişmentli desteğiyle güçlenip sonra üstünlüğü ele almıştır', ['Danişmentliler Selçukluları tamamen yıkmıştır', 'İki beylik Bizans\'a bağlanmıştır', 'Danişmentliler Moğollara sığınmıştır'], 'I. Mesud tahta Danişmentli Gümüştekin\'in desteğiyle çıktı; Danişmentlilerin zayıflamasıyla Selçuklular Anadolu\'da öne geçti.'),
  ('II. Kılıçarslan\'ın Miryokefalon\'dan önce Danişmentlileri ortadan kaldırması Selçukluların Bizans\'la mücadelesini nasıl etkilemiştir?', 'Doğudaki rakibi bertaraf edip bütün gücü batıya yöneltmesini sağlamıştır', ['Bizans\'la kalıcı barış yapmasına yol açmıştır', 'Selçukluları Haçlılarla ittifaka zorlamıştır', 'Başkentin Sivas\'a taşınmasına neden olmuştur'], 'Danişmentlilerin yıkılmasıyla Anadolu\'daki Türk birliği güçlendi; II. Kılıçarslan Bizans\'a karşı tek başına güçlü bir rakip hâline geldi.'),
  ('Bizans İmparatoru Manuel Komnenos\'un Miryokefalon yenilgisini 1071\'deki büyük yenilgiye benzetmesi hangi savaşa göndermedir?', 'Malazgirt Savaşı', ['Pasinler Savaşı', 'Dandanakan Savaşı', 'Katvan Savaşı'], 'Manuel, Miryokefalon yenilgisini Malazgirt felaketine benzettiği bir mektup yazmıştır.'),
  ('Türkiye Selçuklularında Kayseri, Sivas, Konya gibi şehirlerin hem kervan yollarının kavşağında bulunması hem de sultanların bu şehirlerde vakit geçirmesi neyi gösterir?', 'Ticaret ve yönetim merkezlerinin iç içe geliştiğini', ['Selçukluların başkenti hiç olmadığını', 'Bu şehirlerin yalnızca askerî kale olduğunu', 'Ticaretin yalnızca kıyı şehirlerinde yapıldığını'], 'Anadolu\'nun büyük şehirleri hem kervan yollarının hem de saltanat merkezlerinin buluştuğu yerlerdi; ticaret şehirleri canlandırdı.'),
  ('Türkiye Selçuklu sultanı II. İzzeddin Keykavus ile kardeşi IV. Kılıçarslan\'ın birlikte tahta oturması hangi dış etkinin sonucudur?', 'Moğolların ülkeyi kardeşler arasında bölmesi', ['Halifenin taht için hakemlik yapması', 'Bizans\'ın Konya\'yı işgali', 'Memlüklerin Anadolu\'yu yönetmesi'], 'Kösedağ sonrası Moğollar, Selçuklu ülkesini kardeşler arasında paylaştırarak devleti zayıf tutmaya çalıştı.'),
  ('Harzemşah hükümdarı Alaeddin Muhammed\'in Abbasi halifesi Nasır ile çatışmasının temel nedeni nedir?', 'Bağdat\'ta kendi adına hutbe okutup halifeliği denetleme isteği', ['Halifenin Moğollarla savaşmayı reddetmesi', 'Halifenin Harezm\'i ele geçirmesi', 'Halifenin Selçuklu sultanını tahta çıkarması'], 'Alaeddin Muhammed, Selçukluların halife üzerindeki konumunu üstlenmek istedi; halife ise buna karşı çıkıp onu engellemeye çalıştı.'),
  ('Vakıf kuran kişinin vakfın amaçlarını, gelirlerini ve yönetimini belirttiği belgeye ne ad verilir?', 'Vakfiye', ['Berat', 'Menşur', 'Ahitname'], 'Vakfiyeler, vakfın şartlarını ve gelir kaynaklarını kayda geçiren belgelerdir; dönemin sosyal hayatı için değerli kaynaklardır.'),
  ('Türk-İslam devletlerinde gayrimüslim tebaaya \'zimmî\' denmesi, onların hukuki konumu hakkında neyi ifade eder?', 'Belirli bir vergi karşılığında koruma altında olduklarını', ['Askerlik yapmak zorunda olduklarını', 'Hiçbir hakka sahip olmadıklarını', 'Devlet yönetiminden sorumlu olduklarını'], 'Zimmîler cizye ödeyerek can, mal ve inanç güvenliğini korur; kendi dinî kurumlarını yaşatabilirlerdi.'),
  ('Müslüman çiftçilerden ürünün belirli bir oranı olarak alınan toprak vergisine ne denirdi?', 'Öşür', ['Cizye', 'Haraç', 'Ağnam'], 'Öşür \'onda bir\' anlamına gelir ve Müslümanların topraklarından alınan ürün vergisiydi; gayrimüslimlerin toprağından ise haraç alınırdı.'),
  ('Selçuklu şehirlerinde aynı meslekten esnafın aynı çarşıda toplanması aşağıdakilerden hangisini kolaylaştırmıştır?', 'Kalite ve fiyat denetimini', ['Vergiden kaçınmayı', 'Yabancı tüccarın dışlanmasını', 'Üretimin durmasını'], 'Aynı meslek erbabının bir arada çalışması, muhtesip ve Ahi teşkilatının denetimini kolaylaştırırdı.'),
  ('Türk-İslam devletlerinde \'Darü\'l-hadis\' adı verilen kurumlar hangi amaçla kurulmuştur?', 'Hadis ilminin öğretilmesi', ['Hastaların tedavisi', 'Ordunun eğitimi', 'Yabancı elçilerin ağırlanması'], 'Darü\'l-hadisler, Hz. Muhammed\'in sözlerini ve hadis usulünü öğreten uzmanlaşmış eğitim kurumlarıydı.'),
  ('Selçuklu sarayında yetişen gulamların eğitimini anlatan Siyasetname\'deki aşamalı terfi sistemi, gulamlardan hangi özelliği bekler?', 'Sadakat ve deneyimle kademe kademe yükselmeyi', ['Doğrudan komutan olarak işe başlamayı', 'Yalnızca soyluluk nedeniyle terfi etmeyi', 'Ticaretle zenginleşmeyi'], 'Nizamülmülk\'e göre gulam yıllarca hizmet ederek ve sadakatini kanıtlayarak çadır başı, hacib ve emir gibi kademelere yükselirdi.'),
  ('Türk-İslam devletlerinde hükümdarın sarayında devlet işlerini düzenleyen, kabul törenlerini yöneten ve sultan ile halk arasında iletişimi sağlayan görevliye ne denirdi?', 'Hacib', ['Müstevfi', 'Ariz', 'Müşrif'], 'Hacib, saray teşrifatından sorumluydu; Selçuklularda \'Emir-i hacib\' sarayın en önemli görevlilerindendi.'),
  ('Selçuklularda haberleşmeyi sağlayan ve aynı zamanda istihbarat görevi gören teşkilatın Nizamülmülk tarafından önemsenmesinin nedeni nedir?', 'Ülkedeki gelişmelerden ve görevlilerin davranışlarından haberdar olmak', ['Ticaret kervanlarına vergi koymak', 'Medreselere öğrenci toplamak', 'Yabancı elçileri eğlendirmek'], 'Nizamülmülk, berid ve casusluk teşkilatının ihmal edilmesini devlet için büyük tehlike olarak görüyordu.'),
  ('Türklerin İslamiyet\'i kabulünden sonra eski Türk gelenekleriyle İslami unsurların kaynaşması, aşağıdaki örneklerden hangisinde görülür?', 'Kurultay geleneğinin divan teşkilatıyla birlikte sürmesi', ['Arap alfabesinin bırakılması', 'Kurultayın tamamen yasaklanması', 'Halifenin Türk hükümdarı olması'], 'Selçuklularda kurultay geleneği sürerken İslami divan kurumları da benimsendi; böylece iki gelenek kaynaştı.'),
  ('Maveraünnehir ve Horasan\'da hüküm süren, sarayında ve ordusunda Türk gulamlarına geniş yer veren İran asıllı devlet hangisidir?', 'Samanoğulları', ['Büveyhoğulları', 'Saffariler', 'Tahiriler'], 'Samanoğulları Türk gulamları yetiştirerek ordularını güçlendirdi; Alp Tegin ve Sebük Tegin de bu ortamda yetişti.'),
  ('Samanoğullarının Türk bozkırıyla sınırda yürüttüğü ticaret ve tebliğ faaliyetleri, Türklerin İslamlaşmasına nasıl katkıda bulunmuştur?', 'Sınır şehirlerinde Türklerle Müslümanların sürekli temasını sağlamıştır', ['Türkleri zorla Müslüman yapmıştır', 'Türklerin Budizm\'e geçişini hızlandırmıştır', 'Türkleri Hindistan\'a sürmüştür'], 'İsficab, Şaş ve Cend gibi sınır şehirleri ticaret ve dervişler aracılığıyla İslam\'ın bozkıra yayıldığı merkezlerdi.'),
  ('Abbasi halifesi Mütevekkil\'in 861\'de Türk komutanlar tarafından öldürülmesi, Abbasi yönetiminde hangi durumun ortaya çıktığını gösterir?', 'Türk komutanların halifeler üzerinde güçlü bir nüfuz kazandığını', ['Türklerin Abbasi ordusundan çıkarıldığını', 'Halifeliğin Türklere geçtiğini', 'Abbasilerin Bizans\'a bağlandığını'], 'Samarra döneminde Türk komutanlar halifelerin tahta çıkışını ve düşüşünü etkileyecek kadar güçlendi.'),
  ('Karahanlıların Müslüman olmalarının ardından Karahıtay ve Budist Uygurlara karşı mücadele etmeleri, onları hangi rolle öne çıkarmıştır?', 'İslam\'ın doğudaki sınır muhafızlığı', ['Bizans\'ın müttefiki', 'Haçlıların koruyucusu', 'Moğolların vasalı'], 'Karahanlılar, İslam dünyasının doğu sınırında gayrimüslim Türk topluluklarına karşı İslam\'ı koruyup yaydılar.'),
  ('Karahanlılarda hükümdar ailesinin her üyesinin \'tegin\', \'ilig\' gibi unvanlarla bölgelerin yönetimini paylaşması, devletin hangi zaafına yol açmıştır?', 'Merkezî otoritenin zayıflayıp iç çekişmelerin artmasına', ['Ticaretin tamamen durmasına', 'Türkçenin unutulmasına', 'Ordunun yalnızca Araplardan oluşmasına'], 'Hanedan üyelerinin geniş yetkilerle bölge yönetmesi, sık sık bağımsızlık mücadelelerine ve bölünmeye neden oldu.'),
  ('Bir öğrenci, Gazneli Mahmut\'un seferlerini haritada izlerken yönünün ağırlıklı olarak güneydoğuya, Selçukluların fetihlerinin ise batıya olduğunu fark ediyor. Bu farklılığın Türk tarihine etkisi nedir?', 'Gazneliler Hindistan\'ı, Selçuklular Ön Asya ve Anadolu\'yu Türk-İslam dünyasına kattı', ['İki devlet aynı bölgelerde birleşti', 'Her iki devlet de Avrupa\'yı fethetti', 'İki devlet de Çin\'e yöneldi'], 'Gazneliler İslam\'ı Hindistan\'a taşıdı; Selçuklular ise İran, Irak, Suriye ve Anadolu\'da Türk egemenliği kurdu.'),
  ('Selçuk Bey\'in oğulları arasında, Tuğrul ve Çağrı beylerin babası olan kimdir?', 'Mikail', ['Arslan Yabgu', 'Musa Yabgu', 'Yunus'], 'Tuğrul ve Çağrı, Selçuk Bey\'in oğlu Mikail\'in oğullarıdır; Mikail erken yaşta bir savaşta öldü.'),
  ('Selçukluların Karahanlılar ile Gazneliler arasındaki çatışmalarda taraf değiştirerek yer edinmeye çalışması, kuruluş dönemindeki hangi stratejiyi yansıtır?', 'Güçlü devletler arasındaki rekabetten yararlanma', ['Tek bir devlete sürekli bağlı kalma', 'Bizans\'la ittifak kurma', 'Halifeliğe karşı savaş açma'], 'Selçuklular güçlenene kadar bölgedeki büyük devletlerin rekabetini kullanarak varlıklarını sürdürdü.'),
  ('Selçukluların Horasan\'da güç kazanmasında yerel halkın Gazneli vergi memurlarından şikâyetçi olması nasıl bir rol oynamıştır?', 'Halkın Selçukluları kurtarıcı olarak karşılamasını kolaylaştırmıştır', ['Halkın Selçuklulara karşı ayaklanmasına yol açmıştır', 'Halkın Hindistan\'a göç etmesine neden olmuştur', 'Gaznelilerin Horasan\'da güçlenmesini sağlamıştır'], 'Ağır Gazneli vergilerinden bunalan Nişabur ve Merv halkı, Selçuklulara kapılarını açtı.'),
  ('Dandanakan\'dan sonra Çağrı Bey\'in doğu bölgelerini, Tuğrul Bey\'in batı bölgelerini yönetmesi hangi eski Türk geleneğinin sürdürüldüğünü gösterir?', 'İkili teşkilat', ['Ülkenin halifeye ait olması', 'Tek merkezli yönetim', 'Askerî vesayet'], 'Eski Türk devletlerinde ülke doğu ve batı olarak ikiye ayrılırdı; Selçuklular da bu geleneği sürdürdü.'),
  ('Tuğrul Bey döneminde Selçukluların Anadolu\'ya düzenlediği akınlar ve Pasinler Savaşı\'nın ardından Bizans\'la yapılan antlaşma Selçuklulara hangi kazanımı sağlamıştır?', 'Bizans\'ın Selçuklu gücünü tanıması', ['İstanbul\'un teslim edilmesi', 'Anadolu\'nun tamamen alınması', 'Bizans\'ın Haçlılara savaş açması'], 'Pasinler sonrası Bizans barış isteyip elçi gönderdi; böylece Selçukluların bölgedeki gücü resmen kabul edilmiş oldu.'),
  ('Büyük Selçuklu sultanı Muhammed Tapar döneminde Batınilere karşı düzenlenen seferlerin ortak amacı nedir?', 'Kalelerini ele geçirip suikast tehdidini ortadan kaldırmak', ['Haçlılarla birlikte Mısır\'ı almak', 'Karahanlıları Selçuklulara bağlamak', 'Halifeyi Bağdat\'tan çıkarmak'], 'Muhammed Tapar, İsfahan yakınındaki Şahdiz gibi Batıni kalelerini aldı; ancak Alamut ele geçirilemedi.'),
  ('Alamut Kalesi\'ndeki Batıni gücüne 1256\'da kesin olarak son veren hükümdar kimdir?', 'Hülagü Han', ['Sultan Sencer', 'Melikşah', 'Baybars'], 'Hülagü, Bağdat\'a yürümeden önce Alamut ve diğer Batıni kalelerini ele geçirdi.'),
  ('Büyük Selçuklu döneminde Sünni-Şii çatışmasının yoğunlaşması ve Nizamiye medreselerinin kurulması birlikte değerlendirildiğinde hangi yargıya ulaşılabilir?', 'Selçuklular eğitimi ideolojik mücadelenin aracı olarak kullanmıştır', ['Selçuklular mezhep konularına hiç ilgi duymamıştır', 'Medreseler yalnız ticaret eğitimi vermiştir', 'Şiilik devletin resmî mezhebi olmuştur'], 'Nizamiyeler Batıni-Fatımi propagandasına karşı Sünni düşünceyi yaymak ve devlete görevli yetiştirmek için kurulmuştu.'),
  ('Sultan Sencer döneminde Merv\'in Büyük Selçuklu başkenti olması ve Sencer\'in türbesinin burada bulunması, onun hangi bölgeye ağırlık verdiğini gösterir?', 'Horasan\'a', ['Anadolu\'ya', 'Irak\'a', 'Suriye\'ye'], 'Sencer uzun süre Horasan meliki olarak Merv\'de yaşadı; sultanlığında da Merv merkez oldu.'),
  ('Sultan Sencer\'in Gazneliler ve Karahanlılar üzerinde üstünlük kurması, devletin doğu sınırlarında nasıl bir tablo oluşturmuştur?', 'Doğu Türk-İslam devletleri Selçuklu egemenliğini tanımıştır', ['Doğu sınırı tamamen Moğollara geçmiştir', 'Gazneliler Selçukluları yönetmiştir', 'Karahanlılar Bizans\'a bağlanmıştır'], 'Sencer Gazne\'ye girerek Behram Şah\'ı tahta çıkardı ve Karahanlıları bağlı hâle getirdi; Katvan\'a kadar doğuda üstünlük Selçukluların oldu.'),
  ('Türkiye Selçukluları ile Büyük Selçuklular arasındaki ilişki dikkate alındığında Türkiye Selçuklularının bağımsız bir devlet olarak hareket etmeye başlaması en çok hangi gelişmeyle hızlanmıştır?', 'Melikşah\'ın ölümünden sonra Büyük Selçukluların zayıflaması', ['Kösedağ Savaşı\'nın kazanılması', 'Bizans\'ın Selçuklulara vergi ödemesi', 'Karahanlıların yıkılması'], 'Melikşah sonrası taht kavgaları Büyük Selçukluların Anadolu üzerindeki denetimini zayıflattı; I. Kılıçarslan bağımsız hareket etti.'),
  ('Türkiye Selçukluları döneminde Antalya\'da yapılan ve yivli gövdesiyle şehrin simgesi olan minare hangisidir?', 'Yivli Minare', ['Kesik Minare', 'İnce Minare', 'Hıdırlık Kulesi'], 'Yivli Minare I. Alaeddin Keykubat döneminde yapılmış, tuğladan yivli gövdesiyle tanınan bir yapıdır.'),
  ('Türkiye Selçuklularında askerî gücün bir kısmını oluşturan, Hristiyan asıllı paralı askerlerin bulunması devletin nasıl bir yapıya sahip olduğunu gösterir?', 'Farklı unsurları orduda kullanan çok kültürlü bir yapı', ['Yalnızca Türkmenlere dayanan bir yapı', 'Askersiz bir devlet yapısı', 'Tamamen Bizans\'a bağlı bir yapı'], 'Selçuklu ordusunda gulamlar, Türkmenler, ikta askerleri ve Frank paralı askerleri bir arada yer alırdı.'),
  ('Türkiye Selçukluları ile Kilikya Ermeni Krallığı arasındaki ilişkilerde Selçukluların asıl hedefi neydi?', 'Akdeniz\'e açılan ticaret yollarını güvenceye almak', ['Ermeni Krallığı\'nı Moğollara karşı korumak', 'Kilikya\'yı Bizans\'a bağlamak', 'Haçlı devletlerine yardım ulaştırmak'], 'Kilikya, Akdeniz kıyısındaki limanlara ve Halep yönüne giden yolların üzerindeydi; Selçuklular bu bölgeyi denetim altında tutmak istedi.'),
  ('Memlük Devleti\'nin ordusunu oluşturan memlüklerin çoğunlukla hangi bölgeden küçük yaşta satın alınarak getirildiği bilinmektedir?', 'Deşt-i Kıpçak ve Kafkasya', ['Endülüs ve Kuzey Afrika', 'Hindistan ve Seylan', 'Yemen ve Habeşistan'], 'İlk dönemde Kıpçak bozkırlarından, sonraki dönemde Kafkasya\'dan (Çerkezler) getirilen gençler kışlalarda eğitilirdi.'),
  ('Memlüklerin küçük yaşta satın alınan gençleri kışlalarda askerî ve dinî eğitimden geçirmesi, bu askerlerin hangi özelliğini güçlendirmiştir?', 'Efendilerine ve birliklerine bağlılığı', ['Ticaret becerisini', 'Denizcilik bilgisini', 'Tarımsal üretkenliği'], 'Ailesinden kopartılan memlükler, yetiştirildikleri efendilerine ve \'hoşdaş\' denilen silah arkadaşlarına bağlılıkla yetişirdi.'),
  ('Baybars döneminde Memlüklerin Moğollara karşı Altın Orda ile ittifak kurması hangi ilkeye dayanır?', 'Ortak düşmana karşı birleşme', ['Aynı hanedandan gelme', 'Ticari rekabet', 'Bizans\'ın arabuluculuğu'], 'Altın Orda da İlhanlılarla düşmandı; Baybars ve Berke Han bu ortak düşmana karşı yakınlaştı.'),
  ('Memlük Devleti\'nde Kahire\'nin Bağdat\'ın yıkılmasından sonra İslam dünyasının bilim merkezlerinden biri olması hangi gelişmeyle ilişkilidir?', 'Moğol istilasından kaçan bilginlerin Mısır\'a sığınması', ['Haçlıların Kahire\'de üniversite kurması', 'Bizans\'ın Kahire\'yi yönetmesi', 'Fatımilerin yeniden güçlenmesi'], 'Moğol yıkımı sonrası birçok âlim Memlük topraklarına sığındı; Kahire ve Dımaşk ilim merkezi oldu.'),
  ('Memlüklerin Hint Okyanusu\'ndan gelen baharatın Akdeniz\'e ulaştığı yolu denetlemesi, devlet gelirleri açısından ne ifade eder?', 'Transit ticaretten büyük gümrük geliri elde etmesini', ['Ticaretin tamamen durmasını', 'Venedik\'e vergi ödemesini', 'Baharatın yasaklanmasını'], 'Kızıldeniz-İskenderiye hattı baharat ticaretinin ana yoluydu; Memlükler bu ticaretten yüksek gelir sağladı.'),
  ('Delhi Türk Sultanlığı hükümdarı İltutmış\'ın Abbasi halifesinden menşur alması neyi amaçlıyordu?', 'Sultanlığının İslam dünyasında meşruiyet kazanmasını', ['Halifeliği Delhi\'ye taşımayı', 'Moğollara bağlanmayı', 'Gaznelileri yeniden kurmayı'], 'İltutmış 1229\'da halifeden menşur ve hil\'at aldı; bu, Delhi Sultanlığı\'nın resmen tanınması anlamına geliyordu.'),
  ('Delhi Sultanlığı\'nda tahta çıkan ilk ve tek kadın sultan kimdir?', 'Raziye Sultan', ['Şecerüddür', 'Terken Hatun', 'Mahperi Hatun'], 'İltutmış\'ın kızı Raziye Sultan 1236-1240 yılları arasında hüküm sürdü.'),
  ('Delhi Sultanlığı\'nda Halaci hanedanından Alaeddin Halaci\'nin pazar fiyatlarını kontrol altına alması ve ordu maaşlarını düzenlemesi hangi amaca yönelikti?', 'Moğollara karşı büyük ve sürekli bir ordu besleyebilmek', ['Ticareti tamamen yasaklamak', 'Halifeye vergi göndermek', 'Bizans\'la ticaret yapmak'], 'Alaeddin Halaci, büyük ordunun düşük maaşla geçinebilmesi için fiyatları sabitledi ve pazarları denetledi.'),
  ('Delhi Sultanlığı\'nı 1398\'de yağmalayarak büyük bir darbe vuran hükümdar kimdir?', 'Timur', ['Cengiz Han', 'Babür', 'Hülagü'], 'Timur\'un 1398 Delhi seferi şehri harap etti ve Tuğluk hanedanını çok zayıflattı.'),
  ('Altın Orda\'nın başkenti olan ve İdil Nehri kıyısında kurulan şehir hangisidir?', 'Saray', ['Kazan', 'Bulgar', 'Astrahan'], 'Batu Han tarafından kurulan Saray şehri (sonra Yeni Saray), Altın Orda\'nın siyasi ve ticari merkeziydi.'),
  ('Emevi valisi Kuteybe bin Müslim\'in fethettiği şehirlerde cami yaptırıp Arap kabilelerini yerleştirmesi hangi amaca hizmet ediyordu?', 'Bölgede kalıcı İslam ve Arap varlığı oluşturmak', ['Türkleri Arap ordusundan çıkarmak', 'Bizans\'la ticareti geliştirmek', 'Çin\'le ittifak yapmak'], 'Kuteybe, fethedilen Buhara ve Semerkant\'ta camiler kurdurup Arap garnizonları yerleştirerek denetimi sağlamaya çalıştı.'),
  ('Türkler arasında İslamiyet\'in yayılmasında Arap fetihlerinden çok tüccarların ve dervişlerin etkili olması neyi gösterir?', 'İslam\'ın Türkler arasında büyük ölçüde barışçı yollarla yayıldığını', ['Türklerin zorla Müslüman edildiğini', 'Türklerin İslam\'dan uzak durduğunu', 'İslam\'ın yalnız saray çevrelerinde kaldığını'], 'Ticaret yollarındaki temaslar ve sufilerin sade anlatımı, Türklerin gönüllü olarak İslam\'a girmesini sağladı.'),
  ('Ahmet Yesevi\'nin türbesi bugün hangi ülkenin sınırları içindedir?', 'Kazakistan', ['Özbekistan', 'Türkmenistan', 'Kırgızistan'], 'Türkistan (Yesi) şehrindeki türbe Timur tarafından yaptırılmış olup Kazakistan\'dadır ve UNESCO Dünya Mirası Listesi\'ndedir.'),
  ('Kaşgarlı Mahmut\'un sözlüğünde kelimelerin Arapça açıklanması ve Türkçe örneklerle desteklenmesi, eserin hangi okuyucu kitlesine yönelik olduğunu gösterir?', 'Arapça bilen ve Türkçe öğrenmek isteyenlere', ['Yalnızca Çinli tüccarlara', 'Bizans saray görevlilerine', 'Türkçe bilmeyen Hint bilginlerine'], 'Eser Arap okurlara Türkçeyi öğretmek amacıyla hazırlandığından açıklamalar Arapçadır.'),
  ('Türkiye Selçuklu Devleti\'nde kervansarayların büyük kısmının sultanlar ve devlet adamları tarafından yaptırılması, ticaretin hangi niteliğini gösterir?', 'Devlet tarafından desteklenip yönlendirilen bir faaliyet olduğunu', ['Tamamen yabancılara bırakıldığını', 'Devletin ticarete karşı olduğunu', 'Yalnızca köylerde yapıldığını'], 'Selçuklularda ticaret, devletin altyapı yatırımları ve güvenlik önlemleriyle desteklenen bir politikaydı.'),
  ('Türkiye Selçuklu ekonomisinde Kırım\'dan gelen kürk ve kölelerle Mısır\'dan gelen şeker ve baharatın Anadolu üzerinden el değiştirmesi hangi kavramla açıklanır?', 'Transit ticaret', ['Kapalı ekonomi', 'Takas ekonomisi', 'İhracat yasağı'], 'Anadolu, kuzey ile güney ve doğu ile batı arasındaki malların geçiş noktasıydı; transit ticaret büyük gelir sağladı.'),
  ('Kösedağ\'dan önce Selçuklu ordusunun Moğollara karşı hazırlıksız yakalanmasında aşağıdakilerden hangisi etkili olmamıştır?', 'Haçlı ordularının Konya\'yı kuşatması', ['Babai İsyanı\'nın orduyu yıpratması', 'Deneyimli komutanların saray entrikalarıyla tasfiye edilmesi', 'II. Gıyaseddin\'in yönetimdeki zayıflığı'], 'Kösedağ öncesinde Konya\'ya yönelik bir Haçlı kuşatması yoktur; diğer seçenekler yenilginin nedenleri arasında sayılır.'),
  ('Hülagü\'nün 1258\'de Bağdat\'ta öldürdüğü son Abbasi halifesi kimdir?', 'Müstasım', ['Nasır', 'Kaim', 'Muktedi'], 'Müstasım-Billah, Bağdat\'ın düşmesinden sonra Hülagü\'nün emriyle öldürüldü.'),
  ('Bağdat\'ın 1258\'de yıkılması sırasında Dicle Nehri\'ne atılan kitapların suyu mürekkep rengine boyadığına dair anlatı, hangi kurumun yok edilişini simgeler?', 'Bağdat kütüphanelerindeki ilim mirasının', ['Nizamiye kışlalarının', 'Selçuklu hazinesinin', 'Bizans elçiliğinin'], 'Kaynaklardaki bu anlatı, Bağdat\'taki büyük kütüphanelerin ve ilim mirasının yağmalanmasının sembolü olmuştur.'),
  ('III. Haçlı Seferi\'nde Akka\'nın Haçlılarca alınmasından sonra İngiltere Kralı Aslan Yürekli Richard ile Selahaddin arasında 1192\'de yapılan antlaşmanın sonucu nedir?', 'Kudüs Müslümanlarda kalmış, Hristiyan hacılara ziyaret izni verilmiştir', ['Kudüs Haçlılara teslim edilmiştir', 'Haçlılar bütün kıyı şehirlerini kaybetmiştir', 'Selahaddin İngiltere\'ye vergi ödemeyi kabul etmiştir'], 'Remle (Yafa) Antlaşması ile Kudüs Müslümanlarda kaldı; Haçlılar kıyı şeridini korudu ve hacılar şehri ziyaret edebildi.'),
  ('Haçlı Seferleri sırasında Avrupalıların Doğu\'dan tanıyıp ülkelerine götürdüğü ürünler arasında aşağıdakilerden hangisi yer alır?', 'Şeker kamışı ve pamuklu kumaş', ['Patates ve mısır', 'Tütün ve kakao', 'Kauçuk ve domates'], 'Haçlılar Doğu\'da şeker, baharat, ipek ve pamuklu kumaşları tanıdı; patates, mısır, tütün ve kakao ise Amerika kökenlidir.'),
  ('Zengilerin 1144\'te Urfa\'yı almasından sonra düzenlenen II. Haçlı Seferi\'nin sonucu ne olmuştur?', 'Haçlılar Dımaşk kuşatmasında başarısız olup geri dönmüştür', ['Haçlılar Urfa\'yı geri almıştır', 'Haçlılar Mısır\'ı fethetmiştir', 'Haçlılar Bağdat\'a girmiştir'], 'Anadolu\'da ağır kayıp veren Haçlı orduları 1148\'de Dımaşk\'ı kuşattı; ancak başarısız olup çekildi.'),
  ('Türk-İslam devletlerinin Haçlılarla mücadelesinde öne çıkan liderler sırasıyla düşünüldüğünde, Urfa\'yı alan, Suriye\'yi birleştiren ve Kudüs\'ü geri alan liderler hangi sırayla verilmiştir?', 'İmadeddin Zengi, Nureddin Zengi, Selahaddin Eyyubi', ['Selahaddin Eyyubi, İmadeddin Zengi, Nureddin Zengi', 'Nureddin Zengi, Selahaddin Eyyubi, İmadeddin Zengi', 'Baybars, Kutuz, Kalavun'], '1144 Urfa (İmadeddin), 1154 Dımaşk ile Suriye birliği (Nureddin), 1187 Kudüs (Selahaddin) sıralaması doğrudur.'),
  ('Danişmentlilerin, I. Kılıçarslan\'ın ve Artukluların I. Haçlı Seferi sonrasında Anadolu\'da Haçlılara karşı başarılar kazanması aşağıdakilerden hangisini gösterir?', 'Anadolu Türklerinin Haçlılara karşı direnebildiğini', ['Haçlıların Anadolu\'yu tamamen ele geçirdiğini', 'Türklerin Haçlılarla ittifak kurduğunu', 'Bizans\'ın Türklerle birleştiğini'], '1101 seferlerinde Haçlı orduları Anadolu\'da Türklerce yok edildi; bu, Türklerin Anadolu\'yu savunabildiğini gösterdi.'),
  ('Karahanlılar ile Gazneliler karşılaştırıldığında, Karahanlıları ayıran özellik aşağıdakilerden hangisidir?', 'Türkçeye ve Türk geleneklerine daha sıkı bağlı kalmaları', ['Hindistan\'a seferler düzenlemeleri', 'Ordularının gulamlardan oluşması', 'Farsçayı saray dili yapmaları'], 'Gazneliler İran kültürünün güçlü etkisinde kalırken Karahanlılar Türkçeyi resmî ve edebî dil olarak kullandı.'),
  ('Aşağıdaki Türk-İslam devletlerinden hangisi Hint Yarımadası\'nda kurulmamıştır?', 'Harzemşahlar', ['Delhi Türk Sultanlığı', 'Babür İmparatorluğu', 'Gazneliler'], 'Harzemşahlar Harezm ve İran merkezliydi; diğerleri Hindistan\'da kurulmuş ya da Hindistan\'ı merkez edinmiştir.'),
  ('Aşağıdakilerden hangisi Büyük Selçuklu Devleti\'nin yıkılmasının nedenleri arasında gösterilemez?', 'Haçlıların İsfahan\'ı ele geçirmesi', ['Taht kavgaları', 'Atabeylerin bağımsızlaşması', 'Katvan yenilgisi ve Oğuz isyanı'], 'Haçlılar İsfahan\'a hiç ulaşmadı; diğer seçenekler Büyük Selçukluların dağılmasına yol açan iç ve dış etkenlerdir.'),
  ('Aşağıdaki devletlerden hangisi Büyük Selçuklu Devleti\'nin dağılmasından sonra onun topraklarında kurulan atabeyliklerden biri değildir?', 'Karakoyunlular', ['Zengiler', 'İldenizliler', 'Salgurlular'], 'Karakoyunlular 14. yüzyılda kurulmuş bir Türkmen devletidir; diğerleri Selçuklu atabeyliklerindendir.'),
  ('Aşağıdaki hükümdar-olay eşleştirmelerinden hangisi doğrudur?', 'I. İzzeddin Keykavus – Sinop\'un fethi', ['I. Kılıçarslan – Miryokefalon', 'Melikşah – Dandanakan', 'Alparslan – Katvan'], 'Sinop 1214\'te I. İzzeddin Keykavus döneminde alındı; Miryokefalon II. Kılıçarslan\'a, Dandanakan Tuğrul ve Çağrı\'ya, Katvan Sencer\'e aittir.'),
  ('1040, 1071, 1176 ve 1243 yılları Selçuklu tarihinin dönüm noktalarıdır. Bu yıllarla eşleşen olaylardan hangisi Selçuklular açısından yenilgiyle sonuçlanmıştır?', '1243', ['1040', '1071', '1176'], '1040 Dandanakan, 1071 Malazgirt, 1176 Miryokefalon zaferdir; 1243 Kösedağ ise Moğollara karşı alınmış bir yenilgidir.'),
  ('Melikşah 1072\'de tahta çıkıp 1092\'de ölmüştür. Celali Takvimi 1079\'da yürürlüğe girdiğine göre takvim, Melikşah\'ın tahta çıkışından kaç yıl sonra kabul edilmiştir?', 'Yedi yıl sonra', ['Beş yıl sonra', 'On yıl sonra', 'On iki yıl sonra'], '1079 - 1072 = 7; takvim, Melikşah\'ın tahta çıkışından yedi yıl sonra yürürlüğe girmiştir.'),
  ('Bir tarihçi \'Bu hükümdar hem halifeden sultan unvanını resmen alan ilk Türk hükümdarıdır hem de Bizans\'la ilk büyük savaşı onun döneminde yapılmıştır.\' diyor. Sözü edilen hükümdar kimdir?', 'Tuğrul Bey', ['Alparslan', 'Gazneli Mahmut', 'Melikşah'], 'Tuğrul Bey 1058\'de halifeden resmen sultan unvanını aldı; Pasinler Savaşı (1048) da onun döneminde yapıldı.'),
  ('Delhi Sultanlığı\'nın kurucusu Kutbeddin Aybek\'in köle kökenli olması nedeniyle bu ilk hanedana verilen ad nedir?', 'Memlük (Köleler) Hanedanı', ['Halaci Hanedanı', 'Tuğluk Hanedanı', 'Lodi Hanedanı'], 'Kutbeddin Aybek ve halefleri memluk kökenli olduğundan bu hanedan Köleler Hanedanı olarak da anılır.'),
  ('Türk-İslam devletlerinde kullanılan \'gulam\' kavramı ile Memlük Devleti\'ndeki \'memluk\' kavramı arasındaki ortak nokta nedir?', 'Küçük yaşta alınıp eğitilen asker kökenli kişileri ifade etmeleri', ['Toprak sahibi köylüleri ifade etmeleri', 'Tüccar sınıfını ifade etmeleri', 'Dinî görevlileri ifade etmeleri'], 'Her iki kavram da satın alınarak ya da esir edilerek saray ve kışlalarda yetiştirilen askerleri anlatır.'),
  ('Anadolu\'da Danişmentli, Saltuklu ve Mengücekli beylerinin yaptırdığı cami ve medreseler, Türklerin Anadolu\'ya bakışı hakkında neyi gösterir?', 'Anadolu\'yu kalıcı yurt olarak benimsediklerini', ['Anadolu\'yu geçici bir akın alanı saydıklarını', 'Anadolu\'da yalnız göçebe kalmak istediklerini', 'Anadolu\'yu Bizans\'a bırakmayı planladıklarını'], 'Kalıcı yapılar inşa etmek, beyliklerin Anadolu\'da sürekli yerleşme niyetini gösterir.'),
  ('Kayseri\'de bulunan ve gövdesi on iki dilimli, külahı konik olan ünlü Selçuklu kümbeti hangisidir?', 'Döner Kümbet', ['Üç Kümbetler', 'Gevher Nesibe Kümbeti', 'Emir Saltuk Kümbeti'], 'Döner Kümbet 13. yüzyılda Şah Cihan Hatun için yapılmıştır; dış yüzeyi hayvan ve bitki figürleriyle süslüdür.'),
  ('El-Cezeri\'nin eserinde tanıttığı fil biçimli su saati, onun hangi alandaki çalışmalarının örneğidir?', 'Mekanik ve otomatik makineler', ['Astronomi gözlemleri', 'Tıp ve cerrahi', 'Dil bilgisi'], 'El-Cezeri\'nin fil saati, su akışını ve mekanizmaları kullanan karmaşık bir otomat tasarımıdır.'),
  ('Bir öğrenci Karahanlı, Gazneli ve Büyük Selçuklu devletlerinin hepsinde hükümdarların halifeden unvan aldığını öğreniyor. Bu bilgiden çıkarılabilecek en doğru sonuç hangisidir?', 'Türk-İslam devletleri meşruiyette halifeliği önemli saymıştır', ['Bu devletler halifeye askerî olarak bağlıydı', 'Halife bu devletlerin sultanlarını kendisi seçiyordu', 'Bu devletler Abbasilere düzenli vergi ödüyordu'], 'Halifeden alınan unvan ve menşurlar hükümdarlara İslam dünyasında meşruiyet sağlıyordu; bu, siyasi bağımlılık anlamına gelmiyordu.'),
  ('Abbasi halifesi Kaim Biemrillah\'ın Tuğrul Bey\'e siyasi yetkileri devretmesi, halifelik kurumunda nasıl bir ayrımın belirginleşmesine yol açmıştır?', 'Dinî liderlik halifede, siyasi yetki sultanda kalmıştır', ['Halife hem dinî hem siyasi yetkiyi tümüyle korumuştur', 'Sultan hem halife hem hükümdar olarak tanınmıştır', 'Halifelik kurumu bütünüyle kaldırılmıştır'], 'Tuğrul Bey\'den itibaren halife dinî lider olarak kalırken siyasi ve askerî işler Selçuklu sultanına geçti.'),
  ('Türkiye Selçuklularında sultanın yazışmalarını yürüten ve devletin dış yazışmalarında kullanılan dil çoğunlukla hangisiydi?', 'Farsça', ['Türkçe', 'Rumca', 'Ermenice'], 'Türkiye Selçuklularında yazışma ve edebiyat dili Farsça, bilim dili Arapça idi; Türkçe halk arasında yaygındı.'),
  ('Selçuklu döneminde Anadolu\'da kurulan şehirlerde cami, medrese, hamam ve çarşının bir arada inşa edilmesi hangi şehircilik anlayışını yansıtır?', 'Dinî, eğitim ve ekonomik hayatın bir merkezde toplandığı şehir anlayışını', ['Şehirlerin yalnızca askerî kale olarak tasarlandığı anlayışı', 'Her yapının şehir dışına kurulduğu bir düzen', 'Ticaretin şehirlerde yasaklandığı bir planlamayı'], 'Selçuklu şehirlerinde cami ve medrese çevresinde çarşı ve hamamlar yer alır, şehir hayatı bu çekirdek etrafında gelişirdi.'),
  ('Selçuklu darüşşifalarında akıl hastalarının tedavisinde müzik ve su sesinden yararlanıldığı bilinmektedir. Bu uygulama Selçuklu tıbbı hakkında neyi gösterir?', 'Ruh sağlığına da önem verildiğini', ['Hastaların tedavi edilmediğini', 'Yalnızca cerrahi yöntemlerin kullanıldığını', 'Darüşşifaların yalnız askerlere açık olduğunu'], 'Müzikle tedavi, Selçuklu ve sonraki Türk-İslam hastanelerinde akıl hastalarının tedavisinde kullanılan bir yöntemdi.'),
  ('Büyük Selçuklu Devleti\'nde Kirman, Irak, Suriye ve Anadolu\'da ayrı Selçuklu kollarının ortaya çıkması, merkezî yönetim açısından ne anlama gelir?', 'Hanedan üyelerine verilen bölgelerin zamanla bağımsızlaşması', ['Halifenin bu bölgeleri doğrudan yönetmeye başlaması', 'Bizans\'ın bu bölgeleri Selçuklulara bırakıp çekilmesi', 'Moğolların bu bölgelere kendi valilerini ataması'], 'Melik olarak gönderilen hanedan üyeleri, merkez zayıfladıkça kendi kollarını kurdu; bu durum ülkenin hanedan ortak malı sayılması anlayışının sonucudur.'),
  ('Kösedağ sonrasında Moğollara karşı direnen Türkmen beyliklerinin çoğunlukla Batı ve Güney Anadolu\'daki uç bölgelerde ortaya çıkmasının nedeni nedir?', 'Bu bölgelerin Moğol denetiminden uzak olması', ['Bu bölgelerde Bizans\'ın güçlü olması', 'Bu bölgelerin çöl olması', 'Bu bölgelerde Haçlıların bulunması'], 'Moğolların asıl gücü Orta ve Doğu Anadolu\'daydı; uçlardaki Türkmenler daha serbest hareket edebiliyordu.'),
  ('Bir tarihçi \'Selçuklu sultanları Fars kültürünü sarayda, Türk geleneklerini orduda ve devlet yönetiminde, İslam\'ı hukukta yaşattı.\' diyor. Bu yargı Selçuklu kültürünün hangi özelliğini vurgular?', 'Farklı kültür unsurlarını birleştiren bir sentez olmasını', ['Yalnızca Türk unsurlarına dayanmasını', 'Bizans kültürünü tamamen benimsemesini', 'İslam\'ı yönetimden tümüyle dışlamasını'], 'Selçuklu medeniyeti Türk, İslam ve İran unsurlarının kaynaşmasıyla oluşmuş bir sentezdir.'),
  ('Bir öğrenci \'İkta sistemi ile vakıf sistemi arasındaki temel fark nedir?\' sorusuna cevap arıyor. Hangisi doğru bir karşılaştırmadır?', 'İkta askerlik karşılığında gelir tahsisidir, vakıf ise gelirin hayra ayrılmasıdır', ['İkta hayır kurumudur, vakıf ise askerî bir düzendir', 'İkisi de toprağın mülkiyetinin köylüye verilmesidir', 'İkta yalnız Bizans\'ta, vakıf yalnız Moğollarda uygulanmıştır'], 'İktada devlet vergi gelirini hizmet karşılığı bırakır; vakıfta bir malın geliri kalıcı olarak kamu yararına ayrılır.'),
  ('Bir Selçuklu ikta sahibinin bölgesindeki köylüye ağır davrandığı ve toprağı kendi malı gibi satmaya kalkıştığı düşünülsün. Nizamülmülk\'ün Siyasetname\'deki görüşlerine göre bu kişiye nasıl davranılmalıdır?', 'İkta elinden alınıp cezalandırılmalıdır', ['Ödüllendirilip ikta alanı genişletilmelidir', 'Halifeye sürgün edilmelidir', 'Bölgenin bağımsız hükümdarı ilan edilmelidir'], 'Nizamülmülk ikta sahiplerinin halka zulmetmemesi gerektiğini, aksi durumda iktanın geri alınmasını öğütlemiştir.'),
  ('Büyük Selçuklu Devleti ile Türkiye Selçuklu Devleti karşılaştırıldığında, Türkiye Selçuklularına özgü olan durum hangisidir?', 'Bizans ve Haçlılarla Anadolu topraklarında sürekli mücadele etmeleri', ['Abbasi halifesini Şii baskısından kurtarmaları', 'Dandanakan Savaşı\'yla kurulmaları', 'Başkentlerinin İsfahan olması'], 'Türkiye Selçukluları Anadolu\'da kurulduğu için Bizans ve Haçlılarla doğrudan karşı karşıya kaldı; diğer seçenekler Büyük Selçuklulara aittir.'),
  ('Malazgirt Savaşı ile Miryokefalon Savaşı arasında hangi ortak özellik vardır?', 'İkisinde de Bizans imparatoru orduya bizzat komuta etmiştir', ['İkisinde de Haçlı ordusu yenilmiştir', 'İkisi de Moğollara karşı yapılmıştır', 'İkisi de Mısır\'da yapılmıştır'], 'Malazgirt\'te Romen Diyojen, Miryokefalon\'da Manuel Komnenos ordunun başındaydı ve her iki savaşta da Türkler kazandı.'),
  ('Bir öğrenci, \'Talas, Dandanakan ve Malazgirt savaşlarının ortak sonucu nedir?\' sorusunu düşünüyor. En uygun yanıt hangisidir?', 'Türklerin batıya ve İslam dünyasına yönelişini kolaylaştırmaları', ['Üçünün de Moğolların yenilgisiyle bitmesi', 'Bizans\'ın Türklerle ittifak kurması', 'Türklerin Çin\'e bağlanması'], 'Talas Türk-Arap yakınlaşmasını, Dandanakan Selçuklu devletini, Malazgirt Anadolu\'nun yolunu açarak Türklerin batıya ilerleyişini sağladı.'),
  ('Selçuklularda bir meliki eğiten atabeyin, melik küçük yaştayken eyalet yönetimini fiilen yürütmesi, bugün hangi kavrama benzetilebilir?', 'Vesayet ya da naiplik', ['Seçimle başa gelme', 'Halk oylaması', 'Meclis denetimi'], 'Atabey, reşit olmayan melik adına yönetimi üstlendiği için vasi ya da naip konumundaydı.'),
  ('Bir öğrenci Memlüklerin Ayn Calut\'tan sonra Abbasi halifeliğini Kahire\'de yaşatmasını, Tuğrul Bey\'in Bağdat\'a girişiyle karşılaştırıyor. İki olayın ortak noktası nedir?', 'Türk hükümdarlarının halifeliği koruyarak meşruiyet kazanması', ['Halifeliğin Türk hanedanına geçmesi', 'Halifenin Türklere savaş açması', 'Halifeliğin tamamen kaldırılması'], 'Hem Tuğrul Bey hem de Baybars halifeyi himaye ederek İslam dünyasında siyasi liderliklerini pekiştirdi.'),
  ('Bir tarih öğretmeni öğrencilerinden İkinci Haçlı Seferi\'nde Anadolu\'dan geçen orduların büyük kayıp vermesinin nedenini açıklamalarını istiyor. Hangi açıklama en tutarlıdır?', 'Türklerin vur-kaç taktiği ve Anadolu\'nun zorlu coğrafyası', ['Bizans\'ın Haçlılara tüm yolları açması', 'Haçlıların Anadolu\'da hiç savaşmaması', 'Haçlıların Moğollarla birlikte hareket etmesi'], 'Selçuklular Haçlıları dağlık geçitlerde vur-kaç akınlarıyla yıprattı; erzak ve su sıkıntısı da kayıpları artırdı.'),
  ('Bir öğrenci Celali Takvimi\'ni incelerken bu takvimin güneş yılına dayandığını okuyor. Bu özellik takvime tarım açısından nasıl bir avantaj sağlamıştır?', 'Mevsimlerle uyumlu olduğundan vergi ve ekim zamanlarını düzenlemeyi kolaylaştırmıştır', ['Ay yılına göre her yıl kaydığı için tarımı zorlaştırmıştır', 'Yalnız dinî bayramları belirlemek için kullanılmıştır', 'Tarımla hiçbir ilişkisi yoktur'], 'Güneş yılına dayalı takvim mevsimlerle örtüşür; hasat ve vergi toplama zamanları buna göre planlanabilir.'),
  ('Bir tarihçi \'Bu devlet, Moğollara karşı İslam dünyasının doğudaki son büyük kalkanıydı ve düştüğünde Anadolu ile Irak savunmasız kaldı.\' diyor. Hangi devletten söz edilmektedir?', 'Harzemşahlar', ['Karahanlılar', 'Gazneliler', 'İhşidiler'], 'Harzemşahların çöküşüyle Moğollar İran\'a, ardından Anadolu ve Irak\'a ulaştı.'),
];
